  const info = await lstat(directory);
  if (!info.isDirectory() || info.isSymbolicLink() || info.uid !== process.getuid() || (info.mode & 0o077))
    throw new FacilitatorError('PRIVATE_OWNERSHIP_DIRECTORY_REQUIRED',503);
