    source:{mode:'live', account:{url:origin+'/accounts/'+accountId,...account, json:undefined},
      ledger:{url:origin+'/ledgers?order=desc&limit=1',...ledger,json:undefined}}};
}
const esc = x => String(x).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function reportHtml(report) {
  const field = (k,v) => '<tr><th>' + esc(k) + '</th><td>' + esc(v ?? 'Not established') + '</td></tr>';
  const rows = [
    ['State',report.status],['Provenance',report.mode],['Observed',report.observedAt],['Network',report.network],
    ['Account',report.accountId],['Ledger',report.ledger.sequence],['Ledger close',report.ledger.closedAt],
    ['Reserve',report.account.minimumReserveXlm+' XLM'],['Spendable',report.account.availableXlm+' XLM'],
    ['Nominal fee headroom',report.account.nominalFeeFloorXlm+' XLM / '+report.account.expectedOperations+' ops'],
    ['Requested inbound amount',report.recipient.amountRequested],['Trustline authorization',report.recipient.authorization],
    ['Inbound capacity',report.recipient.inboundCapacity],['Action required',report.reasons.join(', ') || 'None observed'],
    ['Review notes',report.cautions.join(', ')],
  ].map(([k,v])=>field(k,v)).join('');
  return '<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>SF101 Stellar Merchant Account Readiness</title>'+
   '<style>body{font:15px/1.55 system-ui,sans-serif;margin:3rem auto;max-width:1000px;padding:0 1.5rem;color:#1c2630;background:#f8f9fa}h1{font-size:1.6rem}h2{font-size:1.05rem}table{border-collapse:collapse;width:100%;background:#fff}th,td{border-bottom:1px solid #d8dee3;padding:.7rem;text-align:left;vertical-align:top;overflow-wrap:anywhere}th{width:29%;color:#4a5a67}small{color:#56636c}footer{margin-top:2rem}</style>'+
   '<h1>Merchant account readiness</h1><p>Stellar classic-account receiving and reserves, read-only operator report.</p><table>'+rows+'</table><footer><small>This is not an approval, contract/SAC transfer proof, payment receipt, fee quote or grant acceptance. Exact native Horizon state only; account and trustline state can change after retrieval.</small></footer></html>';
}
export function reportCsv(report) {
  const pairs = [['status',report.status],['mode',report.mode],['network',report.network],['account',report.accountId],
    ['observed_at',report.observedAt],['ledger_sequence',report.ledger.sequence],['minimum_reserve_xlm',report.account.minimumReserveXlm],
    ['spendable_xlm',report.account.availableXlm],['nominal_fee_floor_xlm',report.account.nominalFeeFloorXlm],
    ['requested_amount',report.recipient.amountRequested],['trustline_authorization',report.recipient.authorization],
    ['inbound_capacity',report.recipient.inboundCapacity],['reason_codes',report.reasons.join(';')],['cautions',report.cautions.join(';')]];
  const cell = value=>'"'+String(value??'').replace(/"/g,'""')+'"';
  return 'field,value\n'+pairs.map(x=>x.map(cell).join(',')).join('\n')+'\n';
}

// MIT. Native discovery and retained reads composed with the original SAC reviewer.
import { readFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import { readSellerConfig } from '../sf30-seller-sdk/serve.mjs';
import { formatAtomic } from '../sf16-asset-engine/assets.mjs';
import { amountText, sha256 } from './readiness.mjs';
import { createSacAssetMap, createSacRecipientReviewer, resolveSacRpcEndpoint } from './sac.mjs';
import { compileSellerReadinessPlan, reviewSellerSacReadiness, summarizeMerchantReadiness } from './merchant.mjs';
import { createNativeReader, createReadTransport, loadStellarSdk, fault } from './native-reader.mjs';

const serial = value => JSON.stringify(value);
const key = terms => serial([terms.network,terms.asset]);
const codeOf = error => typeof error?.code === 'string' && /^[A-Z0-9_]{1,100}$/.test(error.code)
  ? error.code : 'NATIVE_READ_FAILED';
const captureRead = async task => { try { return {value:await task()}; } catch (error) { return {error:codeOf(error)}; } };

export async function readMerchantReceivingPlan(configPath, {origin} = {}) {
  const path = resolve(configPath), before = await readFile(path);
  if (before.length > 1024*1024) throw fault('SELLER_CONFIG_TOO_LARGE');
  const config = await readSellerConfig(path), after = await readFile(path);
  if (!before.equals(after)) throw fault('SELLER_CONFIG_CHANGED_DURING_READ');
  if (!config.publicOrigin && !origin) throw fault('SELLER_ORIGIN_REQUIRED');
  const plan = compileSellerReadinessPlan(config,{origin});
  const configuration = {path,bytes:before.length,sha256:sha256(before),publicOrigin:plan.publicOrigin};
  return {config,plan,configuration,planDigest:sha256(serial(plan))};
}

/** The original SAC G-account evaluator remains the only classic receiving engine. */
export async function inspectMerchantReceiving({configPath,origin,assetMap,rpcEndpoints,environment = process.env,
  timeoutMs = 12000,feeOperations = 0,capture,sdk,fetchImpl,liveTransport = false} = {}) {
  origin ??= capture?.publicOrigin;
  const source = await readMerchantReceivingPlan(configPath,{origin});
  if (capture && (capture.planDigest !== source.planDigest || capture.configurationSha256 !== source.configuration.sha256))
    throw fault('CAPTURE_SELLER_PLAN_MISMATCH');
  if (capture && assetMap !== undefined && serial(assetMap) !== serial(capture.inputAssetMap)) throw fault('CAPTURE_ASSET_MAP_MISMATCH');
  if (capture && feeOperations !== capture.feeOperations) throw fault('CAPTURE_FEE_OPERATIONS_MISMATCH');
  assetMap ??= capture?.inputAssetMap ?? undefined;
  sdk ??= await loadStellarSdk();
  const supplied = assetMap ? await createSacAssetMap(assetMap,{sdk}) : null;
  const terms = source.plan.routes.flatMap(route=>route.accepts);
  const selected = rpcEndpoints ?? capture?.endpoints ?? {}, endpoints = {};
  for (const network of new Set(terms.map(term=>term.network))) {
    try { endpoints[network] = {url:resolveSacRpcEndpoint(network,selected,environment)}; }
    catch { if (selected[network] !== undefined) endpoints[network] = selected[network]; }
  }
  if (capture && serial(endpoints) !== serial(capture.endpoints)) throw fault('CAPTURE_ENDPOINTS_MISMATCH');
  const transport = createReadTransport({capture,fetchImpl,liveTransport});
  const native = createNativeReader({sdk,transport,endpoints,environment,timeoutMs});
  const tokens = new Map(), mappings = new Map((supplied?.entries() ?? []).map(row=>[key(row),row]));
  for (const term of terms) if (!tokens.has(key(term))) {
    const result = await captureRead(()=>native.token(term.network,term.asset));
    tokens.set(key(term),result);
    if (result.value?.kind === 'STELLAR_ASSET_CONTRACT' && !mappings.has(key(term))) {
      const token = result.value;
      mappings.set(key(term),{network:term.network,asset:term.asset,classicAsset:token.classic,
        source:`Native SDK verified RPC metadata at ${token.rpcOrigin}; ledger ${token.instanceLedger}; endpoint ${token.endpointDigest}`});
    }
  }
  const resolvedAssetMap = {schema:'stellar-forge.sac-asset-map.v1',assets:[...mappings.values()]};
  const sac = mappings.size ? await createSacRecipientReviewer({assetMap:resolvedAssetMap,rpcEndpoints:endpoints,
    environment,timeoutMs,feeOperations,fetchImpl:transport.fetch,sdk}) : null;
  const reviewer = {review:async payment => {
    const found = tokens.get(key(payment));
    if (!found?.value) throw fault(found?.error ?? 'NATIVE_TOKEN_READ_MISSING');
    const token = found.value, isAccount = sdk.StrKey.isValidEd25519PublicKey(payment.payTo);
    if (!isAccount && !sdk.StrKey.isValidContract(payment.payTo)) throw fault('INVALID_G_ADDRESS');
    const read = await captureRead(()=>native.recipient(payment.network,payment.asset,payment.payTo));
    const nativeResult = {token,amountDecimal:formatAtomic(payment.amount,token.decimals),
      recipient:read.value ?? null,errors:read.error ? [read.error] : []};
    let result;
    if (token.kind === 'STELLAR_ASSET_CONTRACT' && isAccount) {
      result = structuredClone(await sac.review(payment));
    } else {
      result = {schema:'stellar-forge.sac-recipient-readiness.v1',terms:structuredClone(payment),
        mapping:mappings.get(key(payment)) ?? null,classic:null,contract:token.instance,
        observedAtMs:Date.now(),completedAt:new Date().toISOString(),reasons:[],accountAdvisories:[],
        status:token.kind === 'STELLAR_ASSET_CONTRACT' ? 'SAC_RECIPIENT_READY' : 'REVIEW_REQUIRED',
        ready:token.kind === 'STELLAR_ASSET_CONTRACT'};
      if (token.kind === 'CUSTOM_CONTRACT') result.reasons.push('CUSTOM_CONTRACT_RECEIVING_POLICY');
    }
    result.native = nativeResult;
    const add = (code,status='ACTION_REQUIRED') => {
      if (!result.reasons.includes(code)) result.reasons.push(code);
      result.ready = false;
      if (result.status !== 'ACTION_REQUIRED') result.status = status;
    };
    if (read.error) add(read.error,'READ_FAILED');
    else {
      const recipient = read.value;
      if (recipient.authorized === false) add('NATIVE_RECIPIENT_NOT_AUTHORIZED');
      const max = (1n << (isAccount && token.kind === 'STELLAR_ASSET_CONTRACT' ? 63n : 127n)) - 1n;
      if (BigInt(recipient.balanceAtomic) + BigInt(payment.amount) > max) add('TOKEN_BALANCE_LIMIT_EXCEEDED');
      if (result.classic?.recipient.existingBalance !== null && result.classic?.recipient.existingBalance !== undefined &&
        amountText(recipient.balanceAtomic) !== result.classic.recipient.existingBalance)
        add('NATIVE_CLASSIC_BALANCE_CHANGED','REVIEW_REQUIRED');
      if (result.classic && token.classic !== 'native' && recipient.authorized !== null &&
        (result.classic.recipient.authorization === 'AUTHORIZED') !== recipient.authorized)
        add('NATIVE_CLASSIC_AUTHORIZATION_CHANGED','REVIEW_REQUIRED');
      const ledgers = [token.instanceLedger,...token.metadataLedgers,recipient.balanceLedger,
        ...(recipient.authorizationLedger ? [recipient.authorizationLedger] : [])];
      if (Math.max(...ledgers)-Math.min(...ledgers) > 12) add('NATIVE_LEDGER_SKEW','REVIEW_REQUIRED');
    }
    return result;
  }};
  let report = await reviewSellerSacReadiness(source.config,{reviewer,origin});
  const reads = transport.reads(), now = Date.now();
  const oldest = reads.length ? Math.min(...reads.map(read=>Date.parse(read.observedAt))) : now;
  const changed = await captureRead(()=>readFile(source.configuration.path));
  const configurationUnchanged = changed.value !== undefined && sha256(changed.value) === source.configuration.sha256;
  const sourceReasons = [
    ...(transport.mode !== 'LIVE_NETWORK_READS' ? ['RETAINED_SOURCE_REVIEW'] : []),
    ...(now-oldest > 60000 || now < oldest ? ['OBSERVATION_STALE'] : []),
    ...(!configurationUnchanged ? ['SELLER_CONFIG_CHANGED_DURING_CHECK'] : []),
  ];
  if (sourceReasons.length) report.options = report.options.map(row=> {
    if (!row.readiness) return row;
    const readiness = {...row.readiness,reasons:[...new Set([...row.readiness.reasons,...sourceReasons])],ready:false};
    if (readiness.status === 'SAC_RECIPIENT_READY') readiness.status = 'REVIEW_REQUIRED';
    return {...row,status:readiness.status,readiness};
  });
  report = summarizeMerchantReadiness({...report,mode:transport.mode,configuration:{...source.configuration,
    unchangedAtCompletion:configurationUnchanged},sourceReasons,readCount:reads.length});
  return {plan:source.plan,report,resolvedAssetMap,capture:{schema:'stellar-forge.sf101.merchant-capture.v1',
    planDigest:source.planDigest,configurationSha256:source.configuration.sha256,publicOrigin:source.plan.publicOrigin,
    inputAssetMap:assetMap ?? null,
    endpoints,feeOperations,mode:transport.mode,reads}};
}

export function compareMerchantReadiness(previous,current) {
  if (previous?.schema !== 'stellar-forge.seller-sac-readiness.v1' || !Array.isArray(previous.options)) throw fault('PREVIOUS_REPORT_INVALID');
  // Option position can change; payment identity includes the complete original terms and resource.
  const identity = row => serial([row.routeId,row.method,row.url,row.terms]);
  const reasons = row => row?.readiness?.reasons ?? (row?.errorCode ? [row.errorCode] : []);
  const before = new Map(previous.options.map(row=>[identity(row),row])), seen = new Set(), options = [];
  for (const row of current.options) {
    const id = identity(row), prior = before.get(id); seen.add(id);
    options.push({routeId:row.routeId,optionIndex:row.optionIndex,optionId:row.optionId,
      change:!prior?'ADDED':serial([prior.status,reasons(prior)])===serial([row.status,reasons(row)])?'UNCHANGED':'CHANGED',
      before:prior?.status ?? null,after:row.status,resolved:reasons(prior).filter(code=>!reasons(row).includes(code)),
      introduced:reasons(row).filter(code=>!reasons(prior).includes(code))});
  }
  for (const row of previous.options) if (!seen.has(identity(row))) options.push({routeId:row.routeId,optionIndex:row.optionIndex,
    optionId:row.optionId,change:'REMOVED',before:row.status,after:null,resolved:[],introduced:[]});
  return {previousCompletedAt:previous.completedAt,previousPlanDigest:previous.planDigest,currentPlanDigest:current.planDigest,options};
}

// MIT. Native SAC receiving preflight composed with original SF101 and SF16.
import { isDeepStrictEqual } from 'node:util';
import { amountText, evaluateSnapshots, fetchOfficialSnapshots, sha256, validateGAddress } from './readiness.mjs';
import { validatePaymentTerms } from '../sf16-asset-engine/assets.mjs';

const I64_MAX = (1n << 63n) - 1n;
const NETWORKS = Object.freeze({
  'stellar:testnet': { horizon:'testnet', passphrase:'Test SDF Network ; September 2015', rpc:'https://soroban-testnet.stellar.org' },
  'stellar:pubnet': { horizon:'public', passphrase:'Public Global Stellar Network ; September 2015' },
});
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const check = (condition, code) => { if (!condition) throw new SacReadinessError(code); };
const freeze = value => { if (object(value) || Array.isArray(value)) { Object.values(value).forEach(freeze); Object.freeze(value); } return value; };
const keyFor = (network, asset) => `${network}|${asset}`;
function nativeStroops(value) {
  check(typeof value === 'string' && /^(?:0|[1-9][0-9]{0,14})(?:\.[0-9]{1,7})?$/.test(value), 'INVALID_NATIVE_BALANCE');
  const [whole,fraction=''] = value.split('.');
  const amount = BigInt(whole)*10000000n+BigInt(fraction.padEnd(7,'0'));
  check(amount <= I64_MAX, 'INVALID_NATIVE_BALANCE');
  return amount;
}

export class SacReadinessError extends Error {
  constructor(code, report) { super(code); this.name = 'SacReadinessError'; this.code = code; if (report) this.report = report; }
}

function termsCopy(input) {
  check(object(input), 'PAYMENT_TERMS_REQUIRED');
  const terms = structuredClone(input);
  check(terms.scheme === 'exact' && Object.hasOwn(NETWORKS, terms.network), 'UNSUPPORTED_PAYMENT_PROFILE');
  check(typeof terms.asset === 'string' && /^C[A-Z2-7]{55}$/.test(terms.asset), 'SAC_CONTRACT_REQUIRED');
  validateGAddress(terms.payTo);
  check(typeof terms.amount === 'string' && /^[1-9][0-9]{0,18}$/.test(terms.amount) && BigInt(terms.amount) <= I64_MAX,
    'CLASSIC_RECIPIENT_AMOUNT_OUT_OF_RANGE');
  return freeze(terms);
}

/** Bind an operator's classic asset to its reserved SAC using the official SDK. */
export async function createSacAssetMap(input, { sdk } = {}) {
  check(object(input) && input.schema === 'stellar-forge.sac-asset-map.v1' && Array.isArray(input.assets) &&
    input.assets.length > 0 && input.assets.length <= 200, 'SAC_ASSET_MAP_REQUIRED');
  const original = structuredClone(input);
  sdk ??= await import('@stellar/stellar-sdk');
  const entries = new Map();
  for (const row of original.assets) {
    check(object(row) && Object.hasOwn(NETWORKS, row.network), 'INVALID_SAC_ASSET_NETWORK');
    const native = row.classicAsset === 'native';
    if (!native) {
      check(object(row.classicAsset) && /^[A-Za-z0-9]{1,12}$/.test(row.classicAsset.code ?? ''), 'INVALID_CLASSIC_ASSET');
      validateGAddress(row.classicAsset.issuer);
    }
    let derived;
    try {
      const asset = native ? sdk.Asset.native() : new sdk.Asset(row.classicAsset.code, row.classicAsset.issuer);
      derived = asset.contractId(NETWORKS[row.network].passphrase);
    } catch { throw new SacReadinessError('SAC_DERIVATION_FAILED'); }
    check(row.asset === derived, 'SAC_CONTRACT_ASSET_MISMATCH');
    check(typeof row.source === 'string' && row.source.length >= 12 && row.source.length <= 512, 'ASSET_SOURCE_REQUIRED');
    const key = keyFor(row.network, row.asset);
    check(!entries.has(key), 'DUPLICATE_SAC_ASSET');
    entries.set(key, freeze({network:row.network, asset:derived, classicAsset:row.classicAsset, decimals:7, source:row.source}));
  }
  return Object.freeze({ get:(network, asset) => entries.get(keyFor(network, asset)), entries:() => [...entries.values()] });
}

export function resolveSacRpcEndpoint(network, endpoints, environment) {
  const selected = endpoints[network];
  let raw = NETWORKS[network].rpc;
  if (selected !== undefined) {
    check(object(selected) && Object.keys(selected).every(key => ['url','urlEnv'].includes(key)) &&
      (selected.url === undefined) !== (selected.urlEnv === undefined), 'INVALID_RPC_ENDPOINT');
    if (selected.urlEnv !== undefined) {
      check(typeof selected.urlEnv === 'string' && /^[A-Za-z_][A-Za-z0-9_]{0,127}$/.test(selected.urlEnv), 'INVALID_RPC_ENVIRONMENT_NAME');
      raw = environment[selected.urlEnv];
    } else raw = selected.url;
  }
  check(typeof raw === 'string' && raw.length <= 4096, 'RPC_ENDPOINT_REQUIRED');
  let url;
  try { url = new URL(raw); } catch { throw new SacReadinessError('INVALID_RPC_ENDPOINT'); }
  check(url.protocol === 'https:' && !url.username && !url.password && !url.hash, 'RPC_HTTPS_REQUIRED');
  return url.href;
}

async function rpcRead(url, method, params, {fetchImpl, timeoutMs}) {
  check(['getNetwork','getLedgerEntries'].includes(method), 'RPC_READ_METHOD_REQUIRED');
  const id = `sf101-${method}`, controller = new AbortController();
  const timer = setTimeout(() => controller.abort(), timeoutMs);
  try {
    let response;
    try {
      response = await fetchImpl(url, {method:'POST', headers:{'content-type':'application/json',accept:'application/json'},
        body:JSON.stringify({jsonrpc:'2.0',id,method,params}), redirect:'manual', signal:controller.signal});
    } catch { throw new SacReadinessError('RPC_TRANSPORT_FAILED'); }
    check(response.ok, `RPC_HTTP_${response.status}`);
    check(response.body, 'RPC_EMPTY_RESPONSE');
    let size = 0; const parts = [];
    for await (const chunk of response.body) {
      size += chunk.length;
      if (size > 1024 * 1024) { controller.abort(); throw new SacReadinessError('RPC_RESPONSE_TOO_LARGE'); }
      parts.push(chunk);
    }
    const bytes = Buffer.concat(parts); let envelope;
    try { envelope = JSON.parse(new TextDecoder('utf-8', {fatal:true}).decode(bytes)); }
    catch { throw new SacReadinessError('RPC_INVALID_JSON'); }
    check(object(envelope) && envelope.jsonrpc === '2.0' && envelope.id === id &&
      !Object.hasOwn(envelope,'error') && object(envelope.result), 'RPC_INVALID_RESULT');
    return {result:envelope.result, source:{method, origin:new URL(url).origin, endpointDigest:sha256(url),
      responseDigest:sha256(bytes), bytes:size}};
  } finally { clearTimeout(timer); controller.abort(); }
}

export function decodeSacInstance({result}, asset, sdk) {
  check(Number.isSafeInteger(result.latestLedger) && result.latestLedger > 0 && Array.isArray(result.entries) &&
    result.entries.length <= 1, 'RPC_INVALID_LEDGER_ENTRIES');
  if (!result.entries.length) return {state:'SAC_INSTANCE_MISSING', latestLedger:result.latestLedger};
  const row = result.entries[0], expected = new sdk.Contract(asset).getFootprint();
  check(object(row) && row.key === expected.toXDR('base64') && typeof row.xdr === 'string' &&
    row.xdr.length <= 512 * 1024, 'RPC_CONTRACT_KEY_MISMATCH');
  let data;
  try { data = sdk.xdr.LedgerEntryData.fromXDR(row.xdr, 'base64').contractData(); }
  catch { throw new SacReadinessError('RPC_CONTRACT_XDR_INVALID'); }
  const expectedData = expected.contractData();
  check(data.contract().toXDR('base64') === expectedData.contract().toXDR('base64') &&
    data.key().toXDR('base64') === expectedData.key().toXDR('base64') &&
    data.durability().value === expectedData.durability().value, 'RPC_CONTRACT_DATA_MISMATCH');
  let executable;
  try { executable = data.val().instance().executable().switch().name; }
  catch { throw new SacReadinessError('RPC_CONTRACT_INSTANCE_INVALID'); }
  check(Number.isSafeInteger(row.lastModifiedLedgerSeq) && row.lastModifiedLedgerSeq > 0 &&
    row.lastModifiedLedgerSeq <= result.latestLedger, 'RPC_CONTRACT_LEDGER_INVALID');
  const liveUntil = row.liveUntilLedgerSeq;
  check(Number.isSafeInteger(liveUntil) && liveUntil >= 0, 'RPC_CONTRACT_LIFETIME_MISSING');
  return {state:executable !== 'contractExecutableStellarAsset' ? 'CONTRACT_EXECUTABLE_NOT_SAC' :
      liveUntil < result.latestLedger ? 'SAC_INSTANCE_ARCHIVED' : 'SAC_INSTANCE_LIVE',
    executable, latestLedger:result.latestLedger, lastModifiedLedger:row.lastModifiedLedgerSeq,
    liveUntilLedger:liveUntil, entryDigest:sha256(Buffer.from(row.xdr,'base64'))};
}

/** One run-scoped reader shares actual account and contract reads across options. */
export async function createSacRecipientReviewer({assetMap, rpcEndpoints = {}, environment = process.env,
  timeoutMs = 12000, feeOperations = 0, fetchImpl = globalThis.fetch, sdk} = {}) {
  check(object(rpcEndpoints) && Object.keys(rpcEndpoints).every(key => Object.hasOwn(NETWORKS,key)), 'INVALID_RPC_ENDPOINTS');
  check(Number.isInteger(timeoutMs) && timeoutMs >= 1000 && timeoutMs <= 30000 && typeof fetchImpl === 'function', 'INVALID_READ_OPTIONS');
  check(Number.isSafeInteger(feeOperations) && feeOperations >= 0 && feeOperations <= 100000, 'INVALID_FEE_OPERATIONS');
  sdk ??= await import('@stellar/stellar-sdk');
  const assets = await createSacAssetMap(assetMap, {sdk});
  const endpoints = structuredClone(rpcEndpoints), cache = new Map();
  const readOptions = {fetchImpl,timeoutMs};
  function cached(key, read) {
    const prior = cache.get(key), now = Date.now();
    if (prior && now - prior.startedAtMs <= 30000) return prior.promise;
    const entry = {startedAtMs:now};
    entry.promise = Promise.resolve().then(read).then(value => ({value, startedAtMs:now}));
    cache.set(key, entry);
    entry.promise.catch(() => { if (cache.get(key) === entry) cache.delete(key); });
    return entry.promise;
  }
  async function review(input) {
    const terms = termsCopy(input), mapping = assets.get(terms.network,terms.asset);
    check(mapping, 'SAC_ASSET_MAPPING_REQUIRED');
    const rpcUrl = resolveSacRpcEndpoint(terms.network,endpoints,environment), endpointId = sha256(rpcUrl);
    const network = await cached(`network|${endpointId}`, () => rpcRead(rpcUrl,'getNetwork',{},readOptions));
    check(network.value.result.passphrase === NETWORKS[terms.network].passphrase, 'RPC_NETWORK_MISMATCH');
    const [horizon, rpc] = await Promise.all([
      cached(`account|${terms.network}|${terms.payTo}`, () => fetchOfficialSnapshots({network:NETWORKS[terms.network].horizon,
        accountId:terms.payTo,timeoutMs,fetchImpl})),
      cached(`contract|${endpointId}|${terms.asset}`, () => rpcRead(rpcUrl,'getLedgerEntries',
        {keys:[new sdk.Contract(terms.asset).getFootprint().toXDR('base64')]},readOptions)),
    ]);
    const observedAtMs = Math.min(network.startedAtMs,horizon.startedAtMs,rpc.startedAtMs), now = Date.now();
    const classic = evaluateSnapshots({...horizon.value, accountId:terms.payTo,network:NETWORKS[terms.network].horizon,
      asset:mapping.classicAsset,inboundAmount:amountText(terms.amount),feeOperations,mode:'live',now:new Date(now)});
    const contract = decodeSacInstance(rpc.value,terms.asset,sdk), reasons = classic.reasons.filter(reason =>
      !['XLM_FEE_FLOOR_NOT_MET','XLM_BELOW_BASE_RESERVE_AND_LIABILITIES'].includes(reason));
    if (contract.state !== 'SAC_INSTANCE_LIVE') reasons.push(contract.state);
    if (Math.abs(contract.latestLedger - classic.ledger.sequence) > 12) reasons.push('RPC_HORIZON_LEDGER_SKEW');
    if (classic.cautions.includes('LEDGER_HEAD_AGE_OUT_OF_RANGE') || now - observedAtMs > 60000 || now < observedAtMs)
      reasons.push('OBSERVATION_STALE');
    if (mapping.classicAsset === 'native') {
