        !HEX64(e.assetDigest) || !HEX64(e.receiptFingerprint) ||
        !(e.transactionFingerprint === null || HEX64(e.transactionFingerprint)) ||
        e.authority !== 'ORIGINAL_NATIVE_PROCESS_SETTLEMENT_SUCCESS' ||
