      Promise.resolve().then(() => {
        controller.signal.throwIfAborted();
        return admit(input);
      }),
      interruption,
    ]);
    controller.signal.throwIfAborted();
    return answer;
  } finally {
    clearTimeout(timer);
    if (onAbort) signal?.removeEventListener('abort', onAbort);
