  const metadata = Object.fromEntries(['schema', 'sourceSha256', 'mode', 'title', 'origin'].map(key => {
    if (typeof snapshot[key] !== 'string') throw new TypeError(`Seller client ${key} required`);
    return [key, snapshot[key]];
