/** Re-read the actual original offer before preparing the selected SF88 config. */
export async function prepareFeedBuyer({ review, intentId, acceptIndex, outputDirectory }) {
  if (!review || typeof review !== 'object') fail('Select the retained original seller offer review.');
  const query = new URLSearchParams(review.query); query.delete('snapshot');
  const current = await readDatasetBuyerOffer({ seller:review.seller, resource:review.resource,
    snapshot:review.snapshot, query:query.toString() });
  const prepared = prepareDatasetBuyer(current, { intentId, acceptIndex, offerSha256:review.offerSha256 });
  const out = await targetDirectory(outputDirectory);
  await exactFile(join(out, 'offer-review.json'), encode(current));
  await exactFile(join(out, 'buyer.json'), Buffer.from(prepared.configText));
  const result = { schema:'stellar-forge.feed-buyer-handoff.v1', snapshot:current.snapshot, resource:current.resource,
    url:current.url, offerSha256:current.offerSha256, configSha256:prepared.configSha256,
    sellerMode:prepared.sellerMode, configuration:join(out, 'buyer.json'), review:join(out, 'offer-review.json') };
  await exactFile(join(out, 'handoff.json'), encode(result));
  return result;
}

const HELP = [
  'Original feed merchant and buyer handoff (Node 22+)',
  '',
  'merchant prepare --dataset-export DIR --state PRIVATE_VERSION_DIR --payment PUBLIC_TERMS.json',
  '  --origin https://api.example --path /feed --out NEW_PACKAGE_DIR --release NEW_RELEASE_DIR',
  '  [--retention-seconds 3600] [--max-versions 4] [--max-retained-bytes 268435456]',
  'merchant serve --release DIR [--port 8423] [--facilitator HTTPS_URL] [--allow-local-facilitator]',
  '',
  'buyer review --seller http://127.0.0.1:8423 --resource https://api.example/feed',
  '  --snapshot ORIGINAL_SNAPSHOT --query "fields=id,title&limit=25" --out NEW_REVIEW.json',
  'buyer prepare --review REVIEW.json --intent UNIQUE_INTENT --accept-index 0 --out NEW_BUYER_DIR',
  '',
  'Read public payment terms from a file. Preparation retains the original SF82 source files,',
  'version-store binding, offer and native CSV contract. Retry unchanged paths to recover a lost reply.',
  'Use the original dataset-refresh command with its current snapshot and revision for later live refresh.',
  'Buyer preparation reloads the actual seller offer and binds the original SF88 configuration to its digest.',
].join('\n');
function args(input) {
  const [family, verb, ...tokens] = input, command = family + ' ' + verb;
  const options = {
    'merchant prepare':['dataset-export','state','payment','origin','path','out','release','retention-seconds','max-versions','max-retained-bytes'],
    'merchant serve':['release','port','facilitator','allow-local-facilitator'],
    'buyer review':['seller','resource','snapshot','query','out'],
    'buyer prepare':['review','intent','accept-index','out'],
  };
  if (!options[command]) fail(HELP);
  const values = Object.create(null);
  for (let i=0;i<tokens.length;i++) {
    const key = tokens[i].startsWith('--') ? tokens[i].slice(2) : '';
    if (!options[command].includes(key) || Object.hasOwn(values,key)) fail('Unknown or duplicate option: ' + tokens[i]);
    if (key === 'allow-local-facilitator') { values[key]=true; continue; }
    if (tokens[i+1] === undefined || tokens[i+1].startsWith('--')) fail('Missing value for ' + tokens[i]);
    values[key] = tokens[++i];
  }
  return { command, values };
}
const need = (values,key) => values[key] || fail('--' + key + ' is required.');
function integer(value, fallback) {
  if (value === undefined) return fallback;
  if (!/^(0|[1-9][0-9]*)$/.test(value) || !Number.isSafeInteger(Number(value))) fail('Choose a nonnegative safe integer.');
  return Number(value);
}
export async function main(input = process.argv.slice(2)) {
  if (input.includes('--help') || input.length < 2) { process.stdout.write(HELP + '\n'); return; }
  const { command, values:v } = args(input);
  let result;
  if (command === 'merchant prepare') result = await prepareFeedMerchant({
    datasetExport:need(v,'dataset-export'), versionDirectory:need(v,'state'), packageDirectory:need(v,'out'),
    releaseDirectory:need(v,'release'), payment:parse(await read(need(v,'payment'),16384)),
    origin:need(v,'origin'), path:v.path ?? '/feed', retentionMs:integer(v['retention-seconds'],3600)*1000,
    maxVersions:integer(v['max-versions'],4), maxRetainedBytes:integer(v['max-retained-bytes'],256*MiB) });
  else if (command === 'merchant serve') {
    const service = await startDatasetRelease(need(v,'release'), { runtime:{ port:integer(v.port,8423),
      ...(v.facilitator ? { facilitator:v.facilitator } : {}),
      ...(v['allow-local-facilitator'] ? { allowLocalFacilitator:true } : {}) } });
    result = { url:service.url, mode:service.mode, snapshot:service.versions.status().current,
      health:service.url + '/_seller/health', offers:service.url + '/_seller/offers', docs:service.url + '/_seller/docs' };
    for (const signal of ['SIGINT','SIGTERM']) process.once(signal, () => {
      void service.close().catch(error => { process.stderr.write(error.message+'\n'); process.exitCode=1; });
    });
  } else if (command === 'buyer review') {
    result = await reviewFeedBuyer({ seller:need(v,'seller'), resource:need(v,'resource'), snapshot:need(v,'snapshot'), query:v.query ?? '' });
    await exactFile(resolve(need(v,'out')),encode(result));
  } else result = await prepareFeedBuyer({ review:parse(await read(need(v,'review'),2*MiB)), intentId:need(v,'intent'),
    acceptIndex:integer(need(v,'accept-index')), outputDirectory:need(v,'out') });
  process.stdout.write(JSON.stringify(result,null,2)+'\n');
  return result;
}
if (process.argv[1] && import.meta.url === pathToFileURL(resolve(process.argv[1])).href)
  main().catch(error=>{process.stderr.write('Feed handoff: '+error.message+'\n');process.exitCode=1;});

"""MIT. Shared console/CLI actions for the retained feed product."""
from feed_workspace import InputError

def execute(ws, body):
    if not isinstance(body, dict):
        raise InputError("Choose a feed action")
    action = body.get("action")
    options = {
        "collection-save": {"collectionId", "title", "members", "newFeeds", "expectedRevision", "operationId"},
        "collection-capture": {"collectionId", "expectedRevision", "expectedRevisions", "operationId", "pageLimit", "force"},
        "collection-resume": {"runId"},
        "collection-edition": {"runId", "name", "fields", "expectedRevisions", "operationId"},
        "register": {"feedId", "config", "expectedRevision", "operationId"},
        "capture": {"feedId", "operationId", "followPages", "pageLimit", "force", "fromCapture"},
        "resume": {"captureId"},
        "apply": {"captureId", "expectedRevision", "operationId", "decisions", "acceptIdentity"},
        "annotate": {"feedId", "identity", "expectedRevision", "operationId", "note", "tags", "starred"},
        "edition": {"feedIds", "name", "fields", "expectedRevisions", "operationId"},
        "query": {"editionId", "params"},
        "compare": {"beforeId", "afterId"},
    }
    if action not in options or set(body) - options[action] - {"action"}:
        raise InputError("Unknown action or action option")
    if action == "collection-save":
        return ws.subscriptions.save(body["collectionId"], body["title"], body["members"], body.get("newFeeds", {}), body["expectedRevision"], body["operationId"])
    if action == "collection-capture":
        return ws.subscriptions.capture(body["collectionId"], body["expectedRevision"], body["expectedRevisions"], body["operationId"], body.get("pageLimit", 100), body.get("force", False))
    if action == "collection-resume":
        return ws.subscriptions.resume(body["runId"])
    if action == "collection-edition":
        return ws.subscriptions.edition(body["runId"], body["name"], body["fields"], body["expectedRevisions"], body["operationId"])
    if action == "register":
        return ws.register(body["feedId"], body["config"], body["expectedRevision"], body["operationId"])
    if action == "capture":
        return ws.capture(body["feedId"], body["operationId"], follow_pages=body.get("followPages", True),
                          page_limit=body.get("pageLimit", 100), force=body.get("force", False),
                          from_capture=body.get("fromCapture"))
    if action == "resume":
        return ws.resume_capture(body["captureId"])
    if action == "apply":
        return ws.apply(body["captureId"], body["expectedRevision"], body["operationId"],
                        body.get("decisions"), body.get("acceptIdentity", False))
    if action == "annotate":
        return ws.annotate(body["feedId"], body["identity"], body["expectedRevision"], body["operationId"],
                           note=body.get("note", ""), tags=body.get("tags"), starred=body.get("starred", False))
    if action == "edition":
        return ws.edition_summary(ws.edition(body["feedIds"], body["name"], body["fields"],
                                 body["operationId"], body["expectedRevisions"]))
    if action == "query":
        return ws.query(ws.edition_view(body["editionId"])["buildId"], body.get("params", {}))
    if action == "compare":
        return ws.compare(ws.edition_view(body["beforeId"])["buildId"], ws.edition_view(body["afterId"])["buildId"])

"""MIT. OPML 1.0/1.1/2.0 subscription outlines over the maintained XML parser."""
from __future__ import annotations
import io
from xml.etree import ElementTree as ET
from original import InputError, parser, parse_stream, expanded, MAX_DEPTH, Node, digest
from feed_source import children, one, txt

MAX_OPML_BYTES = 16 * 1024 * 1024
MAX_OUTLINES = 10000
SCHEMA = "stellar-forge.feed-subscription-source.v1"

def parse_opml(data, validate_url):
    if not isinstance(data, bytes) or not data or len(data) > MAX_OPML_BYTES:
        raise InputError("Choose an original OPML document from 1 byte to 16 MiB")
    p, stack, root, count = parser(), [], None, 0
    def start(name, attributes):
        nonlocal root, count
        count += 1
        if count > MAX_OUTLINES * 2 or len(stack) >= MAX_DEPTH or len(attributes) > 256:
            raise InputError("OPML exceeds this workspace's supported outline shape")
        node = Node(expanded(name), {expanded(k): v for k, v in attributes.items()})
        if stack:
            stack[-1].children.append(node); stack[-1].content.append(node)
        else:
            root = node
        stack.append(node)
    def text(value):
        if stack: stack[-1].content.append(value)
    p.StartElementHandler, p.EndElementHandler, p.CharacterDataHandler = start, lambda _: stack.pop(), text
    parse_stream(p, io.BytesIO(data))
    if root is None or root.name != "opml" or root.attrs.get("version") not in ("1.0", "1.1", "2.0"):
        raise InputError("Choose an OPML document with unnamespaced core elements and version 1.0, 1.1 or 2.0")
    head, body = one(root, "head", True), one(root, "body", True)
    head_values = {}
    for node in head.children:
        if node.name in head_values:
            raise InputError("OPML head repeats " + node.name)
        head_values[node.name] = txt(node)
    entries, outlines = [], 0
    def outline(node, path, folders, inherited_comment=False):
        nonlocal outlines
        outlines += 1
        if outlines > MAX_OUTLINES or "text" not in node.attrs:
            raise InputError("Every OPML outline needs text; at most 10,000 outlines are supported")
        attrs, ident = dict(node.attrs), ".".join(map(str, path))
        for flag in ("isComment", "isBreakpoint"):
            if flag in attrs and attrs[flag] not in ("true", "false"):
                raise InputError("OPML " + flag + " must be true or false")
        commented = inherited_comment or attrs.get("isComment") == "true"
        kind, label = attrs.get("type", "").lower(), attrs["text"]
        row = {"entryId": ident, "attributes": attrs, "children": []}
        if kind == "rss":
            error, url = None, attrs.get("xmlUrl")
            try: validate_url(url)
            except (ValueError, InputError) as problem: error = str(problem)
            entries.append({"entryId": ident, "label": label, "url": url, "folders": folders,
                            "attributes": attrs, "commented": commented, "error": error})
        row["children"] = [outline(c, path + [i + 1], folders + [label], commented)
                           for i, c in enumerate(children(node, "outline"))]
        return row
    tree = [outline(n, [i + 1], []) for i, n in enumerate(children(body, "outline"))]
    if not tree:
        raise InputError("OPML body needs at least one outline")
    return {"schema": SCHEMA, "sourceId": digest(data), "bytes": len(data),
            "version": root.attrs["version"], "head": head_values, "tree": tree, "entries": entries,
            "outlineCount": outlines}

def selected_opml(collection, documents):
    """Produce the selected subscription list; exact input originals are separate files."""
    root = ET.Element("opml", {"version": "2.0"})
    head = ET.SubElement(root, "head")
    ET.SubElement(head, "title").text = collection["title"]
    ET.SubElement(head, "docs").text = "https://opml.org/spec2.opml"
    body = ET.SubElement(root, "body")
    selected = {(m["sourceId"], m["entryId"]) for m in collection["members"]
                if m["enabled"] and m["sourceId"]}
    def copy_node(node, source_id):
        kids = [n for child in node["children"] if (n := copy_node(child, source_id)) is not None]
        chosen = (source_id, node["entryId"]) in selected
        if not chosen and not kids: return None
        attrs = dict(node["attributes"])
        if not chosen:
            attrs = {"text": attrs["text"]}
        # An explicitly selected commented subscription becomes active in this export.
        attrs.pop("isComment", None)
        result = ET.Element("outline", attrs)
        for child in kids: result.append(child)
        return result
    used = [s for s in collection["sources"] if any(key[0] == s for key in selected)]
    for source_id in used:
        doc = documents[source_id]
        target = body if len(used) == 1 else ET.SubElement(body, "outline", {
            "text": doc["head"].get("title") or source_id[:16]})
        for node in doc["tree"]:
            result = copy_node(node, source_id)
            if result is not None: target.append(result)
    configs = {f["id"]: f["config"] for f in collection["feeds"]}
    for member in collection["members"]:
        if member["enabled"] and not member["sourceId"]:
            config = configs[member["feedId"]]
            ET.SubElement(body, "outline", {"text": config["label"], "title": config["label"],
                                          "type": "rss", "xmlUrl": config["url"]})
    if not list(body):
        raise InputError("Select at least one subscription for OPML export")
    return ET.tostring(root, encoding="utf-8", xml_declaration=True)

"""MIT. Private local feed console over the retained original workspace."""
from __future__ import annotations

from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from pathlib import Path
import secrets
import shutil
import threading
import time
from urllib.parse import urlsplit, parse_qs
import uuid
import zipfile

from feed_workspace import FeedWorkspace, InputError, MAX_FEED_BYTES, json_bytes, load_json, digest, checked_id, file_digest
from operations import execute

HERE = Path(__file__).resolve().parent

class BusyError(Exception):
    pass

class LimitedReader:
    def __init__(self, source, remaining):
        self.source, self.remaining = source, remaining
    def read(self, count=-1):
        if not self.remaining:
            return b""
        data = self.source.read(min(self.remaining, count if count >= 0 else self.remaining))
        if not data:
            raise InputError("Upload ended before its declared content length")
        self.remaining -= len(data)
        return data

class OperatorServer(ThreadingHTTPServer):
    daemon_threads = False
    block_on_close = True
    def __init__(self, workspace, port=0):
        self.workspace, self.token = workspace, secrets.token_urlsafe(32)
        self.launch = None
        self.slots = threading.BoundedSemaphore(8)
        self.jobs = threading.RLock()
        self.job, self.worker = None, None
        super().__init__(("127.0.0.1", port), Handler)
        self.origin = "http://127.0.0.1" + ("" if self.server_port == 80 else ":" + str(self.server_port))
        self.hosts = {urlsplit(self.origin).netloc, f"127.0.0.1:{self.server_port}"}
        self.origins = {self.origin, f"http://127.0.0.1:{self.server_port}"}
        self.url = self.origin + "/#" + self.token

    def process_request(self, request, client_address):
        if not self.slots.acquire(blocking=False):
            self.shutdown_request(request); return
        try:
            super().process_request(request, client_address)
        except Exception:
            self.slots.release(); raise
    def process_request_thread(self, request, client_address):
        try:
            super().process_request_thread(request, client_address)
        finally:
            self.slots.release()

    def idle(self):
        with self.jobs:
            if self.job and self.job["state"] == "RUNNING":
                raise BusyError("A workspace action is running; follow its activity before another action")

    def activity(self):
        with self.jobs:
            current = dict(self.job) if self.job else {"state": "IDLE"}
            if current.get("action") in ("capture", "resume") and current["state"] == "RUNNING":
                current["capture"] = getattr(self.workspace, "capture_progress", None)
            if current.get("action") in ("collection-capture", "collection-resume") and current["state"] == "RUNNING":
                current["collection"] = self.workspace.subscriptions.progress
                current["capture"] = getattr(self.workspace, "capture_progress", None)
            return current

    def start(self, body, callback=None, cleanup=None):
        encoded = json_bytes(body)
        ident = digest(encoded)
        with self.jobs:
            if self.job and self.job["id"] == ident and self.job["state"] in ("RUNNING", "DONE"):
                if cleanup: cleanup()
                return self.activity()
            self.idle()
            self.job = {"id": ident, "action": body["action"], "operationId": body.get("operationId"),
                        "state": "RUNNING", "startedAt": time.time()}
            def run():
                try:
                    result = callback() if callback else execute(self.workspace, body)
                    with self.jobs:
                        self.job.update(state="DONE", result=result, completedAt=time.time())
                except Exception as error:
                    with self.jobs:
                        self.job.update(state="FAILED", error=str(error), completedAt=time.time())
                finally:
                    if cleanup: cleanup()
            self.worker = threading.Thread(target=run, name="feed-operation", daemon=False)
            self.worker.start()
            return self.activity()

    def join_worker(self):
        if self.worker:
            self.worker.join()

class Handler(BaseHTTPRequestHandler):
    server_version = "SF30-Feeds"
    protocol_version = "HTTP/1.0"
    def setup(self):
        super().setup()
        self.connection.settimeout(60)
    def log_message(self, *_):
        pass
    def _gate(self, api=True):
        target = urlsplit(self.path)
        if len(self.headers.get_all("Host", [])) != 1 or len(self.headers.get_all("Origin", [])) > 1:
            raise PermissionError("Repeated local host or origin")
        if target.scheme or target.netloc or self.headers.get("Host") not in self.server.hosts:
            raise PermissionError("Invalid local host")
        if self.headers.get("Origin") not in self.server.origins | {None}:
            raise PermissionError("Cross-origin requests are not accepted")
        if api:
            supplied = self.headers.get("Authorization", "")
            if len(self.headers.get_all("Authorization", [])) != 1 or not secrets.compare_digest(
                    supplied.encode(), ("Bearer " + self.server.token).encode()):
                raise PermissionError("Open this process's private console link")
        return target

    def _headers(self, status, media, length, filename=None):
        self.send_response(status)
        self.send_header("Content-Type", media)
        self.send_header("Content-Length", str(length))
        self.send_header("Cache-Control", "no-store")
        self.send_header("X-Content-Type-Options", "nosniff")
        self.send_header("Referrer-Policy", "no-referrer")
        self.send_header("Cross-Origin-Resource-Policy", "same-origin")
        self.send_header("Content-Security-Policy", "default-src 'none'; script-src 'self'; style-src 'self'; connect-src 'self'; base-uri 'none'; form-action 'none'; frame-ancestors 'none'")
        if filename:
            self.send_header("Content-Disposition", f'attachment; filename="{filename}"')
        self.end_headers()

    def _json(self, value, status=200):
        data = json_bytes(value)
        self._headers(status, "application/json; charset=utf-8", len(data))
        self.wfile.write(data)

    def _body(self, maximum=16 * 1024 * 1024):
        raw = self.headers.get("Content-Length", "")
        if self.headers.get("Transfer-Encoding") or len(self.headers.get_all("Content-Length", [])) != 1 or not raw.isdecimal():
            raise InputError("A single Content-Length is required")
        if int(raw) > maximum:
            raise InputError("Upload exceeds this action's size limit")
        return LimitedReader(self.rfile, int(raw))

    def _download(self, path, filename, media="application/octet-stream"):
        with path.open("rb") as stream:
            self._headers(200, media, path.stat().st_size, filename)
            shutil.copyfileobj(stream, self.wfile, 65536)

    def _run(self, callback):
        try:
            callback()
        except PermissionError as error:
            self._json({"error": str(error)}, 403)
        except BusyError as error:
            self._json({"error": str(error), "activity": self.server.activity()}, 409)
        except FileNotFoundError:
            self._json({"error": "The retained item was not found"}, 404)
        except (InputError, ValueError, KeyError, TypeError, zipfile.BadZipFile) as error:
            self._json({"error": str(error)}, 400)
        except (BrokenPipeError, ConnectionResetError, TimeoutError):
            pass
        except Exception as error:
            self._json({"error": "Workspace action failed: " + str(error)}, 500)

    def _query(self, target):
        values = parse_qs(target.query, keep_blank_values=True)
        if any(len(v) != 1 for v in values.values()):
            raise InputError("Repeated query parameters are not accepted")
        return {k: v[0] for k, v in values.items()}

    def do_GET(self):
        self._run(self._get)
    def _get(self):
        target = self._gate(False)
        assets = {"/": ("index.html", "text/html; charset=utf-8"),
                  "/app.js": ("app.js", "text/javascript; charset=utf-8"),
                  "/style.css": ("style.css", "text/css; charset=utf-8"),
                  "/subscriptions": ("subscriptions.html", "text/html; charset=utf-8"),
                  "/subscriptions.js": ("subscriptions.js", "text/javascript; charset=utf-8"),
                  "/subscriptions.css": ("subscriptions.css", "text/css; charset=utf-8")}
        if target.path in assets:
            name, media = assets[target.path]
            data = (HERE / "public" / name).read_bytes()
            self._headers(200, media, len(data)); self.wfile.write(data); return
        self._gate()
        q, ws = self._query(target), self.server.workspace
        if target.path == "/api/launch":
            if self.server.launch is None:
                raise InputError("Open this console with its original structured startup")
            self._json(self.server.launch); return
        if target.path == "/api/activity":
            self._json(self.server.activity()); return
        self.server.idle()
        if target.path == "/api/operation":
            self._json(ws.operation(q["id"], q.get("family", "feed")))
        elif target.path == "/api/subscriptions":
            self._json(ws.subscriptions.state())
        elif target.path == "/api/subscriptions/plan":
            self._json(ws.subscriptions.plan(q["source"]))
        elif target.path == "/api/subscriptions/collection":
            self._json(ws.subscriptions.view(q["id"], int(q["revision"]) if q.get("revision") else None))
        elif target.path == "/api/subscriptions/run":
            self._json(ws.subscriptions.review(q["id"]))
        elif target.path == "/api/subscriptions/original":
            self._download(ws.subscriptions.source_path(q["source"]), q["source"] + ".opml", "text/x-opml")
        elif target.path == "/api/subscriptions/opml":
            data = ws.subscriptions.opml(q["collection"], int(q["revision"]) if q.get("revision") else None)
            self._headers(200, "text/x-opml", len(data), "subscriptions.opml"); self.wfile.write(data)
        elif target.path == "/api/subscriptions/project":
            with ws.mutex, ws.scratch() as temp:
                archive = temp / "feed-collection.zip"
                ws.subscriptions.export(q["binding"], archive)
                self._download(archive, archive.name, "application/zip")
        elif target.path == "/api/state":
            self._json(ws.feed_state())
        elif target.path == "/api/captures":
            self._json(ws.captures(q["feed"], int(q.get("offset", 0)), int(q.get("limit", 50))))
        elif target.path == "/api/review":
            self._json(ws.review(q["capture"], int(q.get("offset", 0)), int(q.get("limit", 50))))
        elif target.path == "/api/requests":
            self._json(ws.requests(q["capture"]))
        elif target.path == "/api/records":
            self._json(ws.records(q["feed"], query=q.get("query", ""), state=q.get("state", "active"),
                                   offset=int(q.get("offset", 0)), limit=int(q.get("limit", 50))))
        elif target.path == "/api/edition":
            self._json(ws.edition_summary(ws.edition_view(q["id"])))
        elif target.path == "/api/changes":
            self._json(ws.comparison_page(q["id"], int(q.get("offset", 0)), int(q.get("limit", 50))))
        elif target.path == "/api/changes/download":
            self._download(ws.comparison_file(q["id"]), "feed-edition-changes.jsonl", "application/x-ndjson")
        elif target.path == "/api/source":
            ident = checked_id(q["sha256"])
            path = ws.root / "sources" / (ident + ".xml")
            if file_digest(path) != ident:
                raise InputError("Retained source bytes changed")
            self._download(path, ident + ".xml", "application/xml")
        elif target.path == "/api/http-body":
            ident = checked_id(q["sha256"])
            path = ws.root / "feed-http" / (ident + ".body")
            if file_digest(path, MAX_FEED_BYTES) != ident:
                raise InputError("Retained HTTP response bytes changed")
            self._download(path, ident + ".body")
        elif target.path in ("/api/export/manifest", "/api/export/file"):
            with ws.mutex, ws.scratch() as temp:
                result = ws.export_edition(q["edition"], temp / "dataset")
                files = result["files"]
                manifest = {"schema": "stellar-forge.feed-dataset-export.v1",
                            "editionId": result["editionId"], "files": files}
                manifest_id = digest(json_bytes(manifest))
                if target.path == "/api/export/manifest":
                    self._json(manifest | {"manifestSha256": manifest_id})
                else:
                    name = q["file"]
                    if q.get("manifest") != manifest_id or name not in files or Path(name).name != name:
                        raise InputError("Select a file from this exact original dataset manifest")
                    path = Path(result["directory"]) / name
                    if file_digest(path) != files[name]["sha256"]:
                        raise InputError("The original dataset file differs from its manifest")
                    self._download(path, name)
        elif target.path in ("/api/export", "/api/project"):
            with ws.mutex, ws.scratch() as temp:
                archive = temp / ("feed-project.zip" if target.path == "/api/project" else "feed-dataset.zip")
                if target.path == "/api/project":
                    ws.export_project(q["edition"], archive)
                else:
                    folder = temp / "dataset"
                    ws.export_edition(q["edition"], folder)
                    with zipfile.ZipFile(archive, "x", compression=zipfile.ZIP_DEFLATED) as out:
                        for source in folder.iterdir():
                            out.write(source, source.name)
                    archive.chmod(0o600)
                self._download(archive, archive.name, "application/zip")
        else:
            self._json({"error": "Unknown local route"}, 404)

    def do_POST(self):
        self._run(self._post)
    def _post(self):
        target = self._gate()
        ws, q = self.server.workspace, self._query(target)
        if target.path == "/api/cancel":
            raw = self._body().read()
            body = load_json(raw) if raw else {}
            if not isinstance(body, dict) or set(body) - {"expectedJobId"}:
                raise InputError("Cancellation accepts only the selected original job ID")
            with self.server.jobs:
                if "expectedJobId" in body and (not self.server.job or
                        self.server.job["id"] != checked_id(body["expectedJobId"]) or self.server.job["state"] != "RUNNING"):
                    raise InputError("The selected original job is no longer running")
                self._json(ws.cancel_capture())
            return
        if target.path == "/api/action":
            body = load_json(self._body().read())
            if not isinstance(body, dict) or not isinstance(body.get("action"), str):
                raise InputError("Choose a feed action")
            self._json(self.server.start(body), 202); return
        self.server.idle()
        if target.path == "/api/subscriptions/import":
            from opml_source import MAX_OPML_BYTES
            data = self._body(MAX_OPML_BYTES).read()
            source_hash = digest(data)
            if q.get("sha256") is not None and checked_id(q["sha256"]) != source_hash:
                raise InputError("The uploaded OPML differs from its selected complete SHA256")
            body = {"action": "opml-import", "operationId": q["operation"], "sha256": source_hash}
            self._json(self.server.start(body, lambda: ws.subscriptions.import_opml(data, q["operation"])), 202)
        elif target.path == "/api/subscriptions/receive":
            from subscriptions import MAX_PACKET
            path = ws.root / "tmp" / ("collection-receive-" + uuid.uuid4().hex + ".zip")
            try:
                with path.open("xb") as output:
                    path.chmod(0o600)
                    shutil.copyfileobj(self._body(MAX_PACKET), output, 65536)
                source_hash = file_digest(path, MAX_PACKET)
                if q.get("sha256") is not None and checked_id(q["sha256"]) != source_hash:
                    raise InputError("The uploaded collection differs from its selected complete SHA256")
                body = {"action": "collection-receive", "operationId": q["operation"], "sha256": source_hash}
                job = self.server.start(body, lambda: ws.subscriptions.receive(path, q["operation"]),
                                        lambda: path.unlink(missing_ok=True))
            except Exception:
                path.unlink(missing_ok=True); raise
            self._json(job, 202)
        elif target.path == "/api/import":
            data = self._body(MAX_FEED_BYTES).read()
            source_hash = digest(data)
            if q.get("sha256") is not None and checked_id(q["sha256"]) != source_hash:
                raise InputError("The uploaded feed differs from its selected complete SHA256")
            body = {"action": "import", "feedId": q["feed"], "operationId": q["operation"],
                    "sourceUrl": q.get("url"), "sha256": source_hash}
            self._json(self.server.start(body, lambda: ws.import_source(q["feed"], data, q["operation"], q.get("url"))), 202)
        elif target.path == "/api/receive":
            path = ws.root / "tmp" / ("feed-receive-" + uuid.uuid4().hex + ".zip")
            try:
                with path.open("xb") as output:
                    path.chmod(0o600)
                    shutil.copyfileobj(self._body(1024 * 1024 * 1024), output, 65536)
                source_hash = file_digest(path, 1024 * 1024 * 1024)
                if q.get("sha256") is not None and checked_id(q["sha256"]) != source_hash:
                    raise InputError("The uploaded project differs from its selected complete SHA256")
                body = {"action": "receive", "operationId": q["operation"], "sha256": source_hash}
                job = self.server.start(body, lambda: ws.receive_project(path, q["operation"]),
                                        lambda: path.unlink(missing_ok=True))
            except Exception:
                path.unlink(missing_ok=True); raise
            self._json(job, 202)
        else:
            self._json({"error": "Unknown local route"}, 404)

"""MIT. Retained subscription collections, original feed capture and native delivery."""
from __future__ import annotations
from collections import Counter
import io
import os
from pathlib import Path
import re
import shutil
import stat
import threading
import time
import zipfile

from original import InputError, checked_id, digest, json_bytes, load_json, file_digest, private_write, regular
from opml_source import parse_opml, selected_opml, MAX_OPML_BYTES

COLLECTION = "stellar-forge.feed-subscription-collection.v1"
RUN = "stellar-forge.feed-collection-capture.v1"
BINDING = "stellar-forge.feed-collection-edition.v1"
PACKET = "stellar-forge.feed-collection-project.v1"
MAX_PACKET = 1536 * 1024 * 1024

def seal(value, field="digest"):
    return value | {field: digest(json_bytes(value))}

def sealed(value, field="digest"):
    return isinstance(value, dict) and value.get(field) == digest(json_bytes({k:v for k,v in value.items() if k != field}))

def child_operation(kind, parent, item=""):
    return "collection-" + kind + "-" + digest(json_bytes([parent, item]))[:48]

class SubscriptionWorkspace:
    def __init__(self, workspace):
        from feed_workspace import identifier, validate_url, origin, normalize_config
        self.ws = workspace
        self.identifier, self.validate_url, self.origin, self.normalize_config = identifier, validate_url, origin, normalize_config
        self.cancelled = threading.Event()
        self.progress = None
        self.db = workspace.db
        self.db.executescript("""
          CREATE TABLE IF NOT EXISTS feed_subscription_sources(id TEXT PRIMARY KEY,body TEXT NOT NULL,created REAL NOT NULL);
          CREATE TABLE IF NOT EXISTS feed_collections(id TEXT PRIMARY KEY,revision INTEGER NOT NULL,body TEXT NOT NULL);
          CREATE TABLE IF NOT EXISTS feed_collection_revisions(id TEXT NOT NULL,revision INTEGER NOT NULL,body TEXT NOT NULL,
            PRIMARY KEY(id,revision));
          CREATE TABLE IF NOT EXISTS feed_collection_runs(id TEXT PRIMARY KEY,collection_id TEXT NOT NULL,body TEXT NOT NULL);
          CREATE TABLE IF NOT EXISTS feed_collection_editions(id TEXT PRIMARY KEY,collection_id TEXT NOT NULL,body TEXT NOT NULL);
          CREATE TABLE IF NOT EXISTS feed_collection_operations(id TEXT PRIMARY KEY,payload TEXT NOT NULL,result TEXT,created REAL NOT NULL);
        """)

    def _begin(self, operation_id, payload):
        self.identifier(operation_id)
        encoded = json_bytes(payload).decode()
        row = self.db.execute("SELECT * FROM feed_collection_operations WHERE id=?", (operation_id,)).fetchone()
        if row:
            if row["payload"] != encoded:
                raise InputError("Subscription operation ID belongs to another action; reopen its exact original request")
            return load_json(row["result"]) if row["result"] else None
        with self.db:
            self.db.execute("INSERT INTO feed_collection_operations VALUES(?,?,NULL,?)",
                            (operation_id, encoded, time.time()))
        return None

    def _done(self, operation_id, result):
        self.db.execute("UPDATE feed_collection_operations SET result=? WHERE id=?", (json_bytes(result).decode(), operation_id))
        return result

    def import_opml(self, data, operation_id):
        document = parse_opml(data, self.validate_url)
        with self.ws.mutex:
            saved = self._begin(operation_id, {"action": "opml-import", "sha256": document["sourceId"]})
            if saved is not None: return saved
            native = self.ws.add_source(io.BytesIO(data), document["head"].get("title", "Subscriptions")[:160], "subscriptions.opml")
            if native["id"] != document["sourceId"]:
                raise InputError("Original XML intake returned another source identity")
            previous = self.db.execute("SELECT body FROM feed_subscription_sources WHERE id=?", (document["sourceId"],)).fetchone()
            if previous and load_json(previous[0]) != document:
                raise InputError("Retained subscription source metadata differs")
            with self.db:
                self.db.execute("INSERT OR IGNORE INTO feed_subscription_sources VALUES(?,?,?)",
                                (document["sourceId"], json_bytes(document).decode(), time.time()))
                return self._done(operation_id, document)

    def source(self, source_id):
        row = self.db.execute("SELECT body FROM feed_subscription_sources WHERE id=?", (checked_id(source_id),)).fetchone()
        if row is None: raise InputError("Unknown original OPML source")
        return load_json(row[0])

    def source_path(self, source_id):
        doc = self.source(source_id)
        path = self.ws.root / "sources" / (source_id + ".xml")
        if file_digest(path, MAX_OPML_BYTES) != doc["sourceId"]:
            raise InputError("Original OPML bytes changed")
        return path

    def plan(self, source_id):
        with self.ws.mutex:
            doc = self.source(source_id)
            current = self.ws.feed_state()["feeds"]
            rows = []
            for item in doc["entries"]:
                matches = [f["id"] for f in current if f["config"]["url"] == item["url"]]
                suggestion = matches[0] if len(matches) == 1 else "feed-" + digest((item["url"] or "").encode())[:20]
                rows.append(item | {"sourceId": source_id, "existingFeedIds": matches,
                                   "suggestedFeedId": suggestion, "selected": not item["commented"] and not item["error"]})
            return {"source": doc, "entries": rows}

    def collection(self, collection_id, revision=None):
        self.identifier(collection_id)
        row = self.db.execute("SELECT body FROM feed_collections WHERE id=?", (collection_id,)).fetchone() if revision is None else \
              self.db.execute("SELECT body FROM feed_collection_revisions WHERE id=? AND revision=?", (collection_id, revision)).fetchone()
        if row is None: raise InputError("Unknown saved subscription collection or revision")
        return load_json(row[0])

    def _members(self, members, documents, configs):
        if not isinstance(members, list) or not 1 <= len(members) <= 10000:
            raise InputError("Choose 1–10,000 subscription entries")
        normalized, seen = [], set()
        entries = {s: {e["entryId"]: e for e in d["entries"]} for s,d in documents.items()}
        for member in members:
            if not isinstance(member, dict) or set(member) != {"sourceId", "entryId", "feedId", "enabled"} or type(member["enabled"]) is not bool:
                raise InputError("Each member needs sourceId, entryId, feedId and an explicit enabled boolean")
            source_id, entry_id, feed_id, enabled = (member[k] for k in ("sourceId", "entryId", "feedId", "enabled"))
            if source_id is None:
                if entry_id is not None or feed_id is None: raise InputError("A manual subscription needs its registered feed ID")
                key = ("feed", feed_id)
                original = None
            else:
                original = entries.get(source_id, {}).get(entry_id)
                if original is None: raise InputError("Subscription is absent from its original OPML")
                key = (source_id, entry_id)
            if key in seen: raise InputError("The same subscription entry occurs twice")
            seen.add(key)
            if feed_id is not None:
                self.identifier(feed_id)
                if feed_id not in configs: raise InputError("Select an existing feed or declare its complete new configuration")
                if original and configs[feed_id]["url"] != original["url"]:
                    raise InputError("Mapped feed URL differs from the exact OPML subscription URL")
            if enabled and (feed_id is None or original and original["error"]):
                raise InputError("An enabled subscription needs a valid original URL and registered feed")
            normalized.append(dict(member))
        enabled_ids = sorted({m["feedId"] for m in normalized if m["enabled"]})
        if not enabled_ids or len(enabled_ids) > 100:
            raise InputError("Enable 1–100 distinct feeds in a collection")
        return normalized

    def save(self, collection_id, title, members, new_feeds, expected_revision, operation_id):
        self.identifier(collection_id)
        if not isinstance(title, str) or not 1 <= len(title) <= 160:
            raise InputError("Collection title needs 1–160 characters")
        if type(expected_revision) is not int or expected_revision < 0 or not isinstance(new_feeds, dict) or not isinstance(members, list):
            raise InputError("Supply the current collection revision and newFeeds configuration object")
        with self.ws.mutex:
            normalized_new = {self.identifier(k): self.normalize_config(k,v) for k,v in new_feeds.items()}
            payload = {"action": "collection-save", "collectionId": collection_id, "title": title, "members": members,
                       "newFeeds": normalized_new, "expectedRevision": expected_revision}
            saved = self._begin(operation_id, payload)
            if saved is not None: return saved
            row = self.db.execute("SELECT revision FROM feed_collections WHERE id=?", (collection_id,)).fetchone()
            if (row[0] if row else 0) != expected_revision:
                raise InputError("Collection revision changed; reload its saved member choices")
            source_ids = sorted({m.get("sourceId") for m in members if isinstance(m,dict) and m.get("sourceId")})
            documents = {s:self.source(s) for s in source_ids}
            requested_ids = {m.get("feedId") for m in members if isinstance(m,dict) and m.get("feedId")}
            if set(normalized_new) - requested_ids:
                raise InputError("New feed configuration is outside the selected collection")
            configs = {}
            for feed_id in requested_ids:
                if feed_id in normalized_new:
                    config = normalized_new[feed_id]
                    existing = self.db.execute("SELECT id FROM feed_sources WHERE id=?", (feed_id,)).fetchone()
                    op_id = child_operation("register", operation_id, feed_id)
                    owned = self.db.execute("SELECT result FROM feed_operations WHERE id=?", (op_id,)).fetchone()
                    if existing and not (owned and owned[0] and self.ws.feed(feed_id)["config"] == config):
                        raise InputError("New feed ID already exists; select that existing feed or choose another ID")
                    configs[feed_id] = config
                else:
                    configs[feed_id] = self.ws.feed(feed_id)["config"]
            normalized = self._members(members, documents, configs)
            # The original registration operation owns each create. If interrupted,
            # this same request replays its completed children before saving the collection.
            for feed_id,config in normalized_new.items():
                self.ws.register(feed_id, config, 0, child_operation("register", operation_id, feed_id))
            now = time.time()
            previous = self.collection(collection_id) if row else None
            value = seal({"schema": COLLECTION, "id": collection_id, "revision": expected_revision + 1,
                          "title": title, "members": normalized, "sources": source_ids,
                          "feeds": [{"id":k,"config":configs[k]} for k in sorted(configs)],
                          "createdAt": previous["createdAt"] if previous else now, "updatedAt": now})
            with self.db:
                self.db.execute("INSERT OR REPLACE INTO feed_collections VALUES(?,?,?)",
                                (collection_id, value["revision"], json_bytes(value).decode()))
                self.db.execute("INSERT INTO feed_collection_revisions VALUES(?,?,?)",
                                (collection_id, value["revision"], json_bytes(value).decode()))
                return self._done(operation_id, value)

    @staticmethod
    def feed_ids(value):
        return sorted({m["feedId"] for m in value["members"] if m["enabled"]})

    def view(self, collection_id, revision=None):
        with self.ws.mutex:
            value = self.collection(collection_id, revision)
            feeds = []
            expected = {f["id"]:f["config"] for f in value["feeds"]}
            for feed_id in self.feed_ids(value):
                try:
                    current = self.ws.feed(feed_id)
                    feeds.append(current | {"configurationChanged": current["config"] != expected[feed_id]})
                except InputError:
                    feeds.append({"id":feed_id,"missing":True,"configurationChanged":True})
            registrations = []
            for item in value["feeds"]:
                current = self.db.execute("SELECT id FROM feed_sources WHERE id=?", (item["id"],)).fetchone()
                registrations.append({"id":item["id"],"retainedConfig":item["config"],"enabled":item["id"] in self.feed_ids(value),
                                      "missing":current is None,"current":self.ws.feed(item["id"]) if current else None})
            return {"collection":value,"feeds":feeds,"registrations":registrations,
                    "missingRegistrations":{f["id"]:f["retainedConfig"] for f in registrations if f["missing"]},
                    "runs":[load_json(r[0]) for r in self.db.execute("SELECT body FROM feed_collection_runs WHERE collection_id=? ORDER BY rowid DESC",(collection_id,))],
                    "editions":[load_json(r[0]) for r in self.db.execute("SELECT body FROM feed_collection_editions WHERE collection_id=? ORDER BY rowid DESC",(collection_id,))],
                    "revisions":[{"revision":r["revision"],"digest":load_json(r["body"])["digest"]}
                                 for r in self.db.execute("SELECT revision,body FROM feed_collection_revisions WHERE id=? ORDER BY revision DESC",(collection_id,))]}

    def state(self):
        with self.ws.mutex:
            return {"schema":COLLECTION, "sources":[{"id":r["id"],"title":load_json(r["body"])["head"].get("title","Subscriptions"),
                        "subscriptions":len(load_json(r["body"])["entries"]),"bytes":load_json(r["body"])["bytes"]}
                        for r in self.db.execute("SELECT * FROM feed_subscription_sources ORDER BY created DESC")],
                    "collections":[{"id":v["id"],"title":v["title"],"revision":v["revision"],"digest":v["digest"],
                        "feeds":len(self.feed_ids(v)),"members":len(v["members"])}
                        for r in self.db.execute("SELECT body FROM feed_collections ORDER BY id") if (v:=load_json(r[0]))]}

    def run(self, run_id):
        row = self.db.execute("SELECT body FROM feed_collection_runs WHERE id=?", (checked_id(run_id),)).fetchone()
        if row is None: raise InputError("Unknown retained collection acquisition")
        return load_json(row[0])

    def _save_run(self, value):
        value["updatedAt"] = time.time()
        with self.db:
            self.db.execute("INSERT OR REPLACE INTO feed_collection_runs VALUES(?,?,?)",
                            (value["id"],value["collectionId"],json_bytes(value).decode()))
        self.progress = {"runId":value["id"],"collectionId":value["collectionId"],"state":value["state"],
                         "counts":dict(Counter(i["state"] for i in value["items"])),
                         "feedId":next((i["feedId"] for i in value["items"] if i["state"]=="RUNNING"),None)}

    def capture(self, collection_id, expected_revision, expected_revisions, operation_id, page_limit=100, force=False):
        if type(page_limit) is not int or not 1 <= page_limit <= 1000 or type(force) is not bool:
            raise InputError("Choose 1–1000 pages per feed and an explicit force boolean")
        if not isinstance(expected_revisions,dict) or any(type(v) is not int for v in expected_revisions.values()):
            raise InputError("Supply the displayed revision of each selected feed")
        with self.ws.mutex:
            collection = self.collection(collection_id, expected_revision)
            payload = {"action":"collection-capture","collectionId":collection_id,"expectedRevision":expected_revision,
                       "collectionDigest":collection["digest"],"expectedRevisions":expected_revisions,"pageLimit":page_limit,"force":force}
            saved = self._begin(operation_id,payload)
            if saved is not None: return saved
            run_id = digest(json_bytes({"operationId":operation_id,"payload":payload}))
            row = self.db.execute("SELECT body FROM feed_collection_runs WHERE id=?", (run_id,)).fetchone()
            if row:
                value = load_json(row[0])
            else:
                if self.collection(collection_id)["revision"] != expected_revision:
                    raise InputError("A newer collection revision exists; review its selection before a new acquisition")
                ids = self.feed_ids(collection)
                if set(ids) != set(expected_revisions):
                    raise InputError("Feed revision choices differ from the complete enabled collection")
                configs = {f["id"]:f["config"] for f in collection["feeds"]}
                for feed_id in ids:
                    current = self.ws.feed(feed_id)
                    if current["revision"] != expected_revisions[feed_id] or current["config"] != configs[feed_id]:
                        raise InputError("Feed changed before collection acquisition: " + feed_id)
                value = {"schema":RUN,"id":run_id,"operationId":operation_id,"collectionId":collection_id,
                         "collectionRevision":expected_revision,"collectionDigest":collection["digest"],"request":payload,
                         "items":[{"feedId":f,"operationId":child_operation("capture",operation_id,f),"state":"PENDING",
                                   "captureId":None,"error":None} for f in ids],"createdAt":time.time(),"state":"RUNNING"}
            if value["state"] == "CAPTURED":
                with self.db: return self._done(operation_id,value)
            self.cancelled.clear()
            value["state"] = "RUNNING"; self._save_run(value)
            configs = {f["id"]:f["config"] for f in collection["feeds"]}
            for item in value["items"]:
                if item["state"] == "CAPTURED": continue
                if self.cancelled.is_set(): break
                item.update(state="RUNNING",error=None); self._save_run(value)
                try:
                    current = self.ws.feed(item["feedId"])
                    if current["revision"] != expected_revisions[item["feedId"]] or current["config"] != configs[item["feedId"]]:
                        raise InputError("Feed changed since this acquisition was selected; preserve this run and choose a new collection acquisition")
                    result = self.ws.capture(item["feedId"],item["operationId"],page_limit=page_limit,force=force)
                    item.update(state="CAPTURED",captureId=result["id"],error=None)
                except Exception as problem:
                    # Original feed_runs already owns the durable partial capture.
                    match = self.db.execute("SELECT id FROM feed_runs WHERE json_extract(body,'$.operationId')=?",
                                            (item["operationId"],)).fetchone()
                    item.update(state="FAILED",captureId=match[0] if match else None,error=str(problem))
                self._save_run(value)
            value["state"] = "CAPTURED" if all(i["state"]=="CAPTURED" for i in value["items"]) else \
                             "CANCELLED" if self.cancelled.is_set() else "PARTIAL"
            self._save_run(value)
            if value["state"] == "CAPTURED":
                with self.db: self._done(operation_id,value)
            return value

    def resume(self, run_id):
        with self.ws.mutex:
            value = self.run(run_id); request = value["request"]
            return self.capture(value["collectionId"],value["collectionRevision"],request["expectedRevisions"],
                                value["operationId"],request["pageLimit"],request["force"])

    def request_cancel(self):
        self.cancelled.set()

    def review(self, run_id):
        with self.ws.mutex:
            value = self.run(run_id)
            rows = []
            for item in value["items"]:
                result = dict(item)
                if item["state"] == "CAPTURED":
                    review = self.ws.review(item["captureId"],0,1)
                    result.update(counts=review["counts"],total=review["total"],feed=review["feed"],
                                  feedIdentityChanged=review["feedIdentityChanged"],application=review["application"])
                rows.append(result)
            return {"run":value,"items":rows}

    def edition(self, run_id, name, fields, expected_revisions, operation_id):
        with self.ws.mutex:
            value = self.run(run_id)
            payload = {"action":"collection-edition","runId":run_id,"name":name,"fields":fields,
                       "expectedRevisions":expected_revisions}
            saved = self._begin(operation_id,payload)
            if saved is not None: return saved
            if value["state"] != "CAPTURED":
                raise InputError("Resume all selected feed acquisitions before creating their combined edition")
            ids = [i["feedId"] for i in value["items"]]
            if not isinstance(expected_revisions,dict) or set(expected_revisions) != set(ids):
                raise InputError("Select the displayed applied revision for every feed")
            for item in value["items"]:
                application = self.db.execute("SELECT body FROM feed_applications WHERE capture_id=?", (item["captureId"],)).fetchone()
                applied = load_json(application[0]) if application else None
                if not applied or applied["revision"] != expected_revisions[item["feedId"]]:
                    raise InputError("Review and apply the selected capture before creating its edition: " + item["feedId"])
                if self.ws.feed(item["feedId"])["revision"] != applied["revision"]:
                    raise InputError("A feed advanced after the selected capture was applied; select a current acquisition")
            native = self.ws.edition(ids,name,fields,child_operation("edition",operation_id),expected_revisions)
            binding = seal({"schema":BINDING,"collectionId":value["collectionId"],"collectionRevision":value["collectionRevision"],
                            "collectionDigest":value["collectionDigest"],"runId":run_id,"editionId":native["id"],
                            "feedRevisions":expected_revisions,"createdAt":time.time()},"id")
            result = {"binding":binding,"edition":self.ws.edition_summary(native)}
            with self.db:
                self.db.execute("INSERT INTO feed_collection_editions VALUES(?,?,?)",
                                (binding["id"],binding["collectionId"],json_bytes(binding).decode()))
                return self._done(operation_id,result)

    def binding(self, binding_id):
        row = self.db.execute("SELECT body FROM feed_collection_editions WHERE id=?", (checked_id(binding_id),)).fetchone()
        if row is None: raise InputError("Unknown collection edition")
        return load_json(row[0])

    def opml(self, collection_id, revision=None):
        with self.ws.mutex:
            value = self.collection(collection_id,revision)
            return selected_opml(value,{s:self.source(s) for s in value["sources"]})

    def export(self, binding_id, output):
        with self.ws.mutex,self.ws.scratch() as temp:
            binding = self.binding(binding_id)
            collection = self.collection(binding["collectionId"],binding["collectionRevision"])
            run = self.run(binding["runId"])
            sources = {s:self.source(s) for s in collection["sources"]}
            history = [load_json(r[0]) for r in self.db.execute(
                "SELECT body FROM feed_collection_revisions WHERE id=? AND revision<=? ORDER BY revision",
                (collection["id"],collection["revision"]))]
            for revision in history:
                for s in revision["sources"]: sources.setdefault(s,self.source(s))
            body = {"schema":PACKET,"collection":collection,"revisionHistory":history,"run":run,"binding":binding,"sources":sources}
            native = temp/"feed-project.zip"
            self.ws.export_project(binding["editionId"],native)
            private_write(temp/"collection.json",json_bytes(body))
            private_write(temp/"subscriptions.opml",selected_opml(collection,sources))
            paths = {"feed-project.zip":native,"collection.json":temp/"collection.json","subscriptions.opml":temp/"subscriptions.opml"}
            for source_id in sources: paths["originals/"+source_id+".opml"] = self.source_path(source_id)
            manifest = {"schema":PACKET,"bindingId":binding_id,"files":{
                name:{"sha256":file_digest(path,MAX_PACKET),"bytes":regular(path,MAX_PACKET).st_size} for name,path in paths.items()}}
            output = Path(output)
            with os.fdopen(os.open(output,os.O_CREAT|os.O_EXCL|os.O_RDWR,0o600),"w+b") as handle:
                owned = os.fstat(handle.fileno())
                try:
                    with zipfile.ZipFile(handle,"w",compression=zipfile.ZIP_DEFLATED) as archive:
                        archive.writestr("manifest.json",json_bytes(manifest))
                        for name,path in paths.items(): archive.write(path,name)
                    handle.flush(); os.fsync(handle.fileno())
                except Exception:
                    try:
                        present = output.lstat()
                        if (present.st_dev,present.st_ino)==(owned.st_dev,owned.st_ino): output.unlink()
                    except FileNotFoundError: pass
                    raise
            return {"bindingId":binding_id,"editionId":binding["editionId"],"file":str(output),
                    "bytes":regular(output,MAX_PACKET).st_size,"sha256":file_digest(output,MAX_PACKET)}

    def receive(self, packet, operation_id):
        packet = Path(packet); packet_sha = file_digest(packet,MAX_PACKET)
        with self.ws.mutex:
            saved = self._begin(operation_id,{"action":"collection-receive","sha256":packet_sha})
            if saved is not None: return saved
            with self.ws.scratch() as temp,zipfile.ZipFile(packet) as archive:
                names, total = set(),0
                for info in archive.infolist():
                    name = info.filename
                    limit = 1024*1024*1024 if name=="feed-project.zip" else 64*1024*1024 if name=="collection.json" else MAX_OPML_BYTES
                    if (name in names or name not in ("manifest.json","collection.json","feed-project.zip","subscriptions.opml") and
                        not re.fullmatch(r"originals/[0-9a-f]{64}\.opml",name) or info.is_dir() or info.flag_bits&1 or
                        stat.S_ISLNK(info.external_attr>>16) or info.compress_type not in (zipfile.ZIP_STORED,zipfile.ZIP_DEFLATED) or info.file_size>limit):
                        raise InputError("Unsupported collection handover member")
                    total += info.file_size; names.add(name)
                    if total>MAX_PACKET or len(names)>10004: raise InputError("Collection handover exceeds its complete supported size")
                    path=temp/name; path.parent.mkdir(mode=0o700,parents=True,exist_ok=True)
                    with archive.open(info) as inp, path.open("xb") as out:
                        path.chmod(0o600); copied=0
                        while data:=inp.read(65536):
                            copied+=len(data)
                            if copied>limit: raise InputError("Collection member exceeds its supported size")
                            out.write(data)
                if not {"manifest.json","collection.json","feed-project.zip","subscriptions.opml"}<=names:
                    raise InputError("Incomplete collection handover")
                manifest=load_json((temp/"manifest.json").read_bytes())
                if manifest.get("schema")!=PACKET or set(manifest.get("files",{}))!=names-{"manifest.json"}:
                    raise InputError("Collection manifest membership differs")
                for name,expected in manifest["files"].items():
                    path=temp/name
                    if expected!={"sha256":file_digest(path,MAX_PACKET),"bytes":regular(path,MAX_PACKET).st_size}:
                        raise InputError("Collection original bytes differ: "+name)
                body=load_json((temp/"collection.json").read_bytes())
                if not isinstance(body,dict) or set(body)!={"schema","collection","revisionHistory","run","binding","sources"} or body["schema"]!=PACKET:
                    raise InputError("Unsupported collection handover body")
                collection,run,binding,sources=(body[k] for k in ("collection","run","binding","sources"))
                if (not sealed(collection) or collection.get("schema")!=COLLECTION or not sealed(binding,"id") or
                    binding.get("schema")!=BINDING or manifest.get("bindingId")!=binding["id"] or
                    binding["collectionId"]!=collection["id"] or binding["collectionRevision"]!=collection["revision"] or
                    binding["collectionDigest"]!=collection["digest"]):
                    raise InputError("Collection edition identity differs")
                if set(sources)!={n[10:-5] for n in names if n.startswith("originals/")}:
                    raise InputError("Original OPML source membership differs")
                for source_id,document in sources.items():
                    data=(temp/"originals"/(checked_id(source_id)+".opml")).read_bytes()
                    if parse_opml(data,self.validate_url)!=document or document["sourceId"]!=source_id:
                        raise InputError("Subscription metadata differs from its original OPML")
                revisions=body["revisionHistory"]
                if not isinstance(revisions,list) or not revisions or len(revisions)>10000:
                    raise InputError("Invalid collection revision history")
                if len({r["revision"] for r in revisions})!=len(revisions) or collection not in revisions:
                    raise InputError("Collection revision history repeats or omits the selected edition")
                for revision in revisions:
                    if not sealed(revision) or revision.get("schema")!=COLLECTION or revision["id"]!=collection["id"] or \
                       type(revision["revision"]) is not int or not 1<=revision["revision"]<=collection["revision"]:
                        raise InputError("Collection historical revision identity differs")
                    configs={f["id"]:self.normalize_config(f["id"],f["config"]) for f in revision["feeds"]}
                    if len(configs)!=len(revision["feeds"]) or any(configs[f["id"]]!=f["config"] for f in revision["feeds"]) or set(revision["sources"])-set(sources):
                        raise InputError("Collection feed/source declaration differs")
                    self._members(revision["members"],{s:sources[s] for s in revision["sources"]},configs)
                if (temp/"subscriptions.opml").read_bytes()!=selected_opml(collection,sources):
                    raise InputError("Selected OPML differs from the saved collection choices")
                request=run.get("request",{})
                expected_keys={"action","collectionId","expectedRevision","collectionDigest","expectedRevisions","pageLimit","force"}
                if (not isinstance(request,dict) or set(request)!=expected_keys or request["action"]!="collection-capture" or
                    request["collectionId"]!=collection["id"] or request["expectedRevision"]!=collection["revision"] or
                    not isinstance(request["expectedRevisions"],dict) or set(request["expectedRevisions"])!=set(self.feed_ids(collection)) or
                    any(type(v) is not int or v<1 for v in request["expectedRevisions"].values()) or
                    type(request["pageLimit"]) is not int or not 1<=request["pageLimit"]<=1000 or type(request["force"]) is not bool):
                    raise InputError("Original collection acquisition request differs")
                self.identifier(run.get("operationId"))
                if (run.get("schema")!=RUN or run.get("state")!="CAPTURED" or run.get("id")!=binding["runId"] or
                    run.get("collectionId")!=collection["id"] or run.get("collectionRevision")!=collection["revision"] or
                    run.get("collectionDigest")!=collection["digest"] or request.get("collectionDigest")!=collection["digest"] or
                    digest(json_bytes({"operationId":run.get("operationId"),"payload":request}))!=run.get("id")):
                    raise InputError("Original collection acquisition identity differs")
                with zipfile.ZipFile(temp/"feed-project.zip") as native:
                    info=native.getinfo("project.json")
                    if info.file_size>256*1024*1024: raise InputError("Original feed project metadata exceeds its supported size")
                    original=load_json(native.read(info))
                edition=original["edition"]
                ids=set(self.feed_ids(collection))
                if (set(f["id"] for f in original["feeds"])!=ids or set(i["feedId"] for i in run["items"])!=ids or
                    len(run["items"])!=len(ids) or binding["editionId"]!=edition["id"] or
                    binding["feedRevisions"]!=edition["revisions"]):
                    raise InputError("Collection and original native edition select different feeds")
                captures={c["id"]:c for c in original["captures"]}
                applications={a["captureId"]:a["body"] for a in original["applications"]}
                frozen_configs={f["id"]:f["config"] for f in collection["feeds"]}
                for item in run["items"]:
                    capture=captures.get(item["captureId"]); applied=applications.get(item["captureId"])
                    if item["state"]!="CAPTURED" or not capture or capture["feedId"]!=item["feedId"] or not applied or \
                       applied["revision"]!=binding["feedRevisions"][item["feedId"]] or capture["operationId"]!=item["operationId"] or \
                       item["operationId"]!=child_operation("capture",run["operationId"],item["feedId"]) or \
                       capture["config"]!=frozen_configs[item["feedId"]]:
                        raise InputError("Collection capture/application join differs")
                # Preflight every collection identity before the original receiver mutates.
                tables=[
                    ("feed_subscription_sources",("id",),[(s,json_bytes(d).decode()) for s,d in sources.items()],"id,body"),
                    ("feed_collection_revisions",("id","revision"),[(r["id"],r["revision"],json_bytes(r).decode()) for r in revisions],"id,revision,body"),
                    ("feed_collections",("id",),[(collection["id"],collection["revision"],json_bytes(collection).decode())],"id,revision,body"),
                    ("feed_collection_runs",("id",),[(run["id"],run["collectionId"],json_bytes(run).decode())],"id,collection_id,body"),
                    ("feed_collection_editions",("id",),[(binding["id"],binding["collectionId"],json_bytes(binding).decode())],"id,collection_id,body")]
                for table,keys,rows,columns in tables:
                    for values in rows:
                        existing=self.db.execute("SELECT "+columns+" FROM "+table+" WHERE "+" AND ".join(k+"=?" for k in keys),
                                                 values[:len(keys)]).fetchone()
                        if existing is not None and tuple(existing)!=values:
                            raise InputError("Existing collection identity differs; receive into a separate workspace")
                native_result=self.ws.receive_project(temp/"feed-project.zip",child_operation("receive",operation_id))
                for source_id in sources:
                    self.ws.add_source(io.BytesIO((temp/"originals"/(source_id+".opml")).read_bytes()),
                                       sources[source_id]["head"].get("title","Subscriptions")[:160],"subscriptions.opml")
                with self.db:
                    for table,keys,rows,columns in tables:
                        for values in rows:
                            if table=="feed_subscription_sources":
                                self.db.execute("INSERT OR IGNORE INTO "+table+" VALUES(?,?,?)",values+(time.time(),))
                            else:
                                self.db.execute("INSERT OR IGNORE INTO "+table+" ("+columns+") VALUES("+",".join("?" for _ in values)+")",values)
                    result={"schema":PACKET,"packetSha256":packet_sha,"collectionId":collection["id"],
                            "collectionRevision":collection["revision"],"bindingId":binding["id"],"editionId":binding["editionId"],
                            "runId":run["id"],"native":native_result}
                    return self._done(operation_id,result)

"""MIT. Complete subscription-library CLI on the original feed workspace."""
from pathlib import Path
from original import InputError, private_write, file_digest
from opml_source import MAX_OPML_BYTES

def add_arguments(sub):
    s = sub.add_parser("subscriptions", help="Retained OPML collections, acquisition, native editions and receiving")
    commands = s.add_subparsers(dest="subscription_command", required=True)
    commands.add_parser("state")
    p = commands.add_parser("import"); p.add_argument("--file",required=True); p.add_argument("--operation",required=True)
    p = commands.add_parser("plan"); p.add_argument("--source",required=True)
    p = commands.add_parser("save"); p.add_argument("--file",required=True,help="JSON collection-save action")
    p = commands.add_parser("show"); p.add_argument("--collection",required=True); p.add_argument("--revision",type=int)
    p = commands.add_parser("capture"); p.add_argument("--collection",required=True); p.add_argument("--revision",type=int,required=True)
    p.add_argument("--revisions",required=True,help="JSON mapping feed IDs to their displayed revisions")
    p.add_argument("--operation",required=True); p.add_argument("--pages",type=int,default=100); p.add_argument("--force",action="store_true")
    p = commands.add_parser("resume"); p.add_argument("--run",required=True)
    p = commands.add_parser("review"); p.add_argument("--run",required=True)
    p = commands.add_parser("edition"); p.add_argument("--run",required=True); p.add_argument("--name",required=True)
    p.add_argument("--fields",required=True); p.add_argument("--revisions",required=True); p.add_argument("--operation",required=True)
    p = commands.add_parser("opml"); p.add_argument("--collection",required=True); p.add_argument("--revision",type=int); p.add_argument("--out",required=True)
    p = commands.add_parser("original"); p.add_argument("--source",required=True); p.add_argument("--out",required=True)
    p = commands.add_parser("export"); p.add_argument("--binding",required=True); p.add_argument("--out",required=True)
    p = commands.add_parser("receive"); p.add_argument("--file",required=True); p.add_argument("--operation",required=True)

def run_command(ws, a, read_json, execute):
    model, c = ws.subscriptions, a.subscription_command
    if c == "state": return model.state()
    if c == "import":
        path=Path(a.file)
        if path.stat().st_size>MAX_OPML_BYTES: raise InputError("Original OPML exceeds 16 MiB")
        return model.import_opml(path.read_bytes(),a.operation)
    if c == "plan": return model.plan(a.source)
    if c == "save":
        action=read_json(a.file)
        if action.get("action")!="collection-save": raise InputError("Choose a collection-save action")
        return execute(ws,action)
    if c == "show": return model.view(a.collection,a.revision)
    if c == "capture": return model.capture(a.collection,a.revision,read_json(a.revisions),a.operation,a.pages,a.force)
    if c == "resume": return model.resume(a.run)
    if c == "review": return model.review(a.run)
    if c == "edition": return model.edition(a.run,a.name,a.fields.split(","),read_json(a.revisions),a.operation)
    if c in ("opml","original"):
        data=model.opml(a.collection,a.revision) if c=="opml" else model.source_path(a.source).read_bytes()
        private_write(Path(a.out),data)
        return {"file":str(Path(a.out).absolute()),"bytes":len(data),"sha256":file_digest(Path(a.out),MAX_OPML_BYTES)}
    if c == "export": return model.export(a.binding,Path(a.out))
    if c == "receive": return model.receive(Path(a.file),a.operation)
    raise InputError("Unknown subscription command")

