SOURCE_SCHEMA = "stellar-forge.fhir-bulk-source.v1"
PLAN_SCHEMA = "stellar-forge.fhir-bulk-mapping.v1"
CONNECTION_SCHEMA = "stellar-forge.fhir-bulk-connection.v1"
