import { startODataMerchant } from './live/merchant.mjs';
import { atomic,readJson,writeNew,formatted,digest,stable,identifier,fault,now } from './state.mjs';

const packageFiles=['catalog.json','plan.json','seller-service.json','offers.json','openapi.json','customer-query.json','request.json','package.json'];
const buyerFiles=['request.json','offers.json','buyer.json','handoff.json'];
const receivedFiles=['original-response.json','rows.jsonl','receiving.json','next-request.json'];
const port=value=>{if(!Number.isInteger(value)||value<0||value>65535)throw fault('ODATA_LIVE_PORT','Choose a valid listener port.');return value;};
function facilitator(value){if(!value)return null;const url=new URL(value);
  if(url.protocol!=='https:'||url.username||url.password||url.hash)throw fault('ODATA_LIVE_FACILITATOR','Use the existing facilitator HTTPS URL.');return url.href;}
async function syncDirectory(directory){const file=await open(directory,'r');try{await file.sync();}finally{await file.close();}}
async function syncTree(directory){for(const entry of await readdir(directory,{withFileTypes:true})){
  const path=join(directory,entry.name);if(entry.isDirectory())await syncTree(path);else{const file=await open(path,'r');try{await file.sync();}finally{await file.close();}}}
  await syncDirectory(directory);}

export async function openODataLiveOperations({workspace,nativeFactoryFor,env=process.env,navigationOrigin=null}={}){
  const root=join(workspace.directory,'live'),products=join(root,'products'),running=new Map();
  await mkdir(products,{recursive:true,mode:0o700});let tail=Promise.resolve(),closing=false;
  function sequence(operation){const task=tail.then(async()=>{if(closing)throw fault('ODATA_LIVE_CLOSED','Reopen live operations.');
    const lease=await acquireReleaseLease(root,'state.lock');try{return await operation();}finally{await lease.close();}});
    tail=task.catch(()=>{});return task;}
  async function profile(id){id=identifier(id,'live service ID');const value=await readJson(join(products,id,'profile.json'));
    if(value.schema!=='stellar-forge.odata-live-profile.v1'||value.id!==id)throw fault('ODATA_LIVE_PROFILE','The retained live service identity differs.',409);return value;}
  const publicRun=run=>run?{state:'RUNNING',mode:run.merchant.mode,url:run.merchant.url,operationsUrl:run.merchant.operations.url,
    startedAt:run.startedAt,snapshot:run.merchant.application.snapshot()}:null;
  const preparedProfile=record=>readPackage(join(products,record.id,'package'),{allowLoopback:record.settings.allowLoopback});
  async function status(){const records=(await workspace.state()).liveProducts;
    return {products:await Promise.all(records.map(async record=>({...record,runtime:publicRun(running.get(record.id)),
      lastRuntime:await readJson(join(products,record.id,'last-runtime.json')).catch(error=>{if(error.code==='ENOENT')return null;throw error;})}))) };}
  async function prepare(input){return sequence(async()=>{
    const id=identifier(input.id,'live service ID'),state=await workspace.state(),saved=state.plans.find(value=>value.id===input.planId);
    if(!saved?.reviewedAt)throw fault('ODATA_LIVE_QUERY','Choose a reviewed saved query.');
    const connection=state.connections.find(value=>value.id===saved.connectionId);
    const plan=await templateFromWorkspace(workspace,{planId:saved.id,publicOrigin:input.origin,payment:input.payment,amountAtomic:input.amount});
    const operation=plan.operations[0],operationId=input.operation||operation.id;
    plan.title=input.name||saved.name;operation.id=operationId;
    if(input.path)operation.path=input.path;
    if(input.maxPageRows!==undefined)operation.maxPageRows=input.maxPageRows;
    if(input.maxTotalRows!==undefined)operation.maxTotalRows=input.maxTotalRows;
    if(saved.query.plan.top!==undefined&&saved.query.plan.top!==null&&operation.maxTotalRows>saved.query.plan.top)
      throw fault('ODATA_LIVE_QUERY_LIMIT','The live query ceiling exceeds the reviewed source row limit.');
    const prepared=await prepareFromWorkspace(workspace,{planId:saved.id,plan,operation:operationId},{allowLoopback:connection.allowLoopback});
    const settings={port:port(input.port??0),operationsPort:port(input.operationsPort??0),facilitator:facilitator(input.facilitator),allowLoopback:connection.allowLoopback===true};
    const directory=join(products,id),record={schema:'stellar-forge.odata-live-profile.v1',id,name:prepared.plan.title,
      planId:saved.id,operation:operationId,sourceBinding:prepared.sourceBinding,createdAt:now(),settings,
      files:['profile.json',...packageFiles.map(name=>'package/'+name)]};
    try{const existing=await profile(id);if(existing.sourceBinding!==record.sourceBinding||stable(existing.settings)!==stable(settings))
        throw fault('ODATA_LIVE_EXISTS','Use a new service ID for changed source or runtime settings.',409);
      await preparedProfile(existing);await workspace.recordLiveProduct(existing);return existing;
    }catch(error){if(error.code!=='ENOENT')throw error;}
    const stage=join(products,'.stage-'+id+'-'+randomUUID());await mkdir(stage,{mode:0o700});
    try{await writePackage(prepared,join(stage,'package'));await writeNew(join(stage,'profile.json'),formatted(record));
      await syncTree(stage);await rename(stage,directory);await syncDirectory(products);
    }finally{await rm(stage,{recursive:true,force:true});}
    await workspace.recordLiveProduct(record);return record;
  });}
  async function start({id}){return sequence(async()=>{
    const record=await profile(id);if(running.has(id))return publicRun(running.get(id));
    const directory=join(products,id),prepared=await preparedProfile(record);
    const lease=await acquireReleaseLease(directory,'run.lock');let merchant;
    try{
      let nativeFactory=null;
      if(record.settings.facilitator){
        if(nativeFactoryFor)nativeFactory=await nativeFactoryFor(record.settings.facilitator);
        else{const [{HTTPFacilitatorClient},{createNativeSellerServer}]=await Promise.all([import('@x402/core/server'),import('../native-factory.mjs')]);
          const facilitatorClient=new HTTPFacilitatorClient({url:record.settings.facilitator});nativeFactory=compiled=>createNativeSellerServer(compiled,{facilitatorClient});}
      }
      merchant=await startODataMerchant({plan:prepared.plan,catalog:prepared.catalog,directory:join(directory,'runtime'),env,
        port:record.settings.port,operationsPort:record.settings.operationsPort,nativeFactory,allowLoopback:record.settings.allowLoopback,navigationOrigin});
      const run={merchant,lease,startedAt:now()};running.set(id,run);
      const result=publicRun(run);await atomic(join(directory,'last-runtime.json'),result);return result;
    }catch(error){running.delete(id);try{await merchant?.close();}finally{await lease.close();}throw error;}
  });}
  async function stopOne(id){const run=running.get(id);if(!run)throw fault('ODATA_LIVE_OWNER','This operator does not have that live service open.',409);
    try{await run.merchant.close();await atomic(join(products,id,'last-runtime.json'),{state:'STOPPED',mode:run.merchant.mode,
      startedAt:run.startedAt,stoppedAt:now(),snapshot:run.merchant.application.snapshot()});}
    finally{running.delete(id);await run.lease.close();}
    return {id,state:'STOPPED'};}
  const stop=({id})=>sequence(()=>stopOne(identifier(id)));
  async function buyer({id,intentId,receivedId}){return sequence(async()=>{
    const record=await profile(id),directory=join(products,id),prepared=await preparedProfile(record);
    const request=receivedId?await readJson(join(directory,'receiving',identifier(receivedId),'next-request.json')):prepared.selection.request;
    if(typeof intentId!=='string'||!intentId.trim())throw fault('ODATA_LIVE_INTENT','Choose the original stable purchase intent.');
    const key=digest(stable({intentId,sourceBinding:record.sourceBinding})),parent=join(directory,'buyers'),target=join(parent,key);
    try{const existing=await readJson(join(target,'handoff.json'));
      if(existing.requestSha256!==digest(formatted(request)))throw fault('ODATA_LIVE_INTENT_CHANGED','That purchase intent already has a different request.',409);
      return {...existing,id:key,files:buyerFiles};}catch(error){if(error.code!=='ENOENT')throw error;}
    await mkdir(parent,{recursive:true,mode:0o700});const stage=join(parent,'.stage-'+key+'-'+randomUUID());
    try{const result=await prepareBuyerHandoff(prepared,{operation:record.operation,request,intentId,directory:stage,requestDirectory:target});
      await syncTree(stage);await rename(stage,target);await syncDirectory(parent);return {...result,id:key,files:buyerFiles};
    }finally{await rm(stage,{recursive:true,force:true});}
  });}
  async function receive({id,bodyBase64}){return sequence(async()=>{
    const record=await profile(id),directory=join(products,id),prepared=await preparedProfile(record);
    if(typeof bodyBase64!=='string'||!bodyBase64.length)throw fault('ODATA_LIVE_RESPONSE','Choose the original saved buyer response.');
    const bytes=Buffer.from(bodyBase64,'base64');if(bytes.toString('base64')!==bodyBase64)throw fault('ODATA_LIVE_RESPONSE','Send the original response as complete base64 bytes.');
    if(bytes.length>16*1024*1024)throw fault('ODATA_LIVE_RESPONSE_SIZE','The original response exceeds 16 MiB.',413);
    const key=digest(bytes),parent=join(directory,'receiving'),target=join(parent,key);
    try{const result=await readJson(join(target,'receiving.json'));return {...result,id:key,files:receivedFiles.filter(name=>name!=='next-request.json'||result.nextRequest)};}
    catch(error){if(error.code!=='ENOENT')throw error;}
    await mkdir(parent,{recursive:true,mode:0o700});const source=join(parent,'.response-'+key+'-'+randomUUID()),stage=join(parent,'.stage-'+key+'-'+randomUUID());
    try{await writeNew(source,bytes);const result=await receivePage(prepared,{operation:record.operation,responsePath:source,directory:stage});
      await syncTree(stage);await rename(stage,target);await syncDirectory(parent);return {...result,directory:target,id:key,files:receivedFiles.filter(name=>name!=='next-request.json'||result.nextRequest)};
    }catch(error){if(error instanceof SyntaxError)throw fault('ODATA_LIVE_RESPONSE_JSON','Choose the original merchant JSON response.',422);throw error;}
    finally{await rm(source,{force:true});await rm(stage,{recursive:true,force:true});}
  });}
  async function collectionStore(id){const record=await profile(id);
    return openServiceCollections({directory:join(products,record.id),profile:record,sequence});}
  const collections=async({id})=>(await collectionStore(id)).list();
  const collection=async({id,collectionId})=>(await collectionStore(id)).inspect(collectionId);
  const collectionRows=async({id,collectionId,offset=0,limit=100})=>(await collectionStore(id)).rows(collectionId,{offset,limit});
  const collect=async({id,collectionId,pages,title,fields,limits})=>(await collectionStore(id)).collect({id:collectionId,pages,title,fields,limits});
  const restoreCollection=async({id,collectionId,sourceManifest,expectedSha256})=>
    (await collectionStore(id)).restore({id:collectionId,sourceManifest,expectedSha256});
  async function comparisonStore(id){const record=await profile(id);
    return openServiceComparisons({directory:join(products,record.id),profile:record,sequence});}
  const comparisons=async({id})=>(await comparisonStore(id)).list();
  const comparison=async({id,comparisonId})=>(await comparisonStore(id)).inspect(comparisonId);
  const comparisonRows=async({id,comparisonId,...options})=>(await comparisonStore(id)).rows(comparisonId,options);
  const compareCollections=async({id,comparisonId,...input})=>(await comparisonStore(id)).create({id:comparisonId,...input});
  const reviewComparison=async({id,comparisonId,...input})=>(await comparisonStore(id)).review(comparisonId,input);
  const publishComparison=async({id,comparisonId,...input})=>(await comparisonStore(id)).publish(comparisonId,input);
  const restoreComparison=async({id,comparisonId,...input})=>(await comparisonStore(id)).restore({id:comparisonId,...input});
  async function file({id,kind='package',recordId,name}){
    if(kind==='collection')return (await collectionStore(id)).file(recordId,name);
    if(kind==='comparison')return (await comparisonStore(id)).file(recordId,name);
    await profile(id);
    const allowed=kind==='package'?packageFiles:kind==='buyer'?[...buyerFiles,'response.json']:kind==='receiving'?receivedFiles:null;
    if(!allowed?.includes(name))throw fault('ODATA_LIVE_FILE','Live service file not found.',404);
    const directory=kind==='package'?join(products,id,'package'):join(products,id,kind==='buyer'?'buyers':'receiving',identifier(recordId));
    return {bytes:await readFile(join(directory,name)),name};}
  async function detail(id){const record=await profile(id),prepared=await preparedProfile(record);
    const list=async(kind,manifest)=>{const directory=join(products,id,kind);let entries;
      try{entries=await readdir(directory,{withFileTypes:true});}catch(error){if(error.code==='ENOENT')return [];throw error;}
      const result=[];for(const entry of entries){if(!entry.isDirectory()||entry.name.startsWith('.'))continue;
        try{result.push({id:entry.name,...await readJson(join(directory,entry.name,manifest))});}catch(error){if(error.code!=='ENOENT')throw error;}}
      return result;};
    return {...record,plan:prepared.plan,selection:prepared.selection,runtime:publicRun(running.get(id)),
      buyers:await list('buyers','handoff.json'),received:await list('receiving','receiving.json')};}
  async function close(){closing=true;await tail;let failure;for(const id of [...running.keys()])try{await stopOne(id);}catch(error){failure??=error;}if(failure)throw failure;}
  return {root,status,prepare,start,stop,buyer,receive,collections,collection,collectionRows,collect,restoreCollection,comparisons,comparison,comparisonRows,compareCollections,reviewComparison,publishComparison,restoreComparison,file,detail,close};
}

// MIT. Paid page handlers share the original OData parser and SF30 supplier runtime.
import { createUpstreamHandlers,closeUpstreamHandlers } from '../../upstream.mjs';
import { parsePage } from '../source.mjs';
import { prepareProduct,runtimeEnvironment } from './config.mjs';
import { buildQuery,cursorCodec,wireFromUrl,nextUrl,operationFor,plain,projectRows,validatePage,PAGE_SCHEMA,integer } from './contract.mjs';
const failure=(status,error)=>({status,headers:{'content-type':'application/json; charset=utf-8'},body:{error}});
export function createODataApplication(input,catalog,{cursorKey,env=process.env,allowLoopback=false,lookup}={}) {
  const prepared=prepareProduct(input,catalog,{allowLoopback}),{plan}=prepared;
  catalog=prepared.catalog;
  const codec=cursorCodec(cursorKey,prepared.sourceBinding,plan.limits.cursorLifetimeSeconds);
  const originals=createUpstreamHandlers(prepared.upstreams,{env:runtimeEnvironment(env),allowLoopback,...(lookup?{lookup}:{})});
  const handlers={},totals={supplierReads:0,deliveredPages:0,deliveredRows:0,rejectedResponses:0},active=new Set();
  let closed=false,closing;
  function request(id,context) {
    if (closed) throw new TypeError('OData merchant is closing');
    if (context?.method!=='POST'||!plain(context.body)||context.url?.search||Object.keys(context.query??{}).length)
      throw new TypeError('Send a JSON OData query object');
    if (Object.hasOwn(context.body,'cursor')) {
      if (Object.keys(context.body).length!==1) throw new TypeError('A continuation is the sole next-page input');
      const saved=codec.decode(context.body.cursor);
      if (saved.operation!==id||!plain(saved.query)||typeof saved.url!=='string') throw new TypeError('Continuation product mismatch');
      const selected=buildQuery(plan,catalog,id,saved.query),{operation}=operationFor(plan,catalog,id);
      integer(saved.seenRows,0,selected.query.top-1,'continuation delivered rows');
      wireFromUrl(catalog,operation,saved.url);
      return {...selected,url:saved.url,seenRows:saved.seenRows};
    }
    return buildQuery(plan,catalog,id,context.body);
  }
  const supplierContext=(operation,context,selected)=>{
    const wire=wireFromUrl(catalog,operation,selected.url),url=new URL(operation.path,plan.publicOrigin);
    for(const [name,value]of Object.entries(wire))url.searchParams.append(name,value);
    return {method:'GET',url,pathParams:{},query:wire,headers:{prefer:selected.compiled.prefer},signal:context.signal};
  };
  for (const operation of plan.operations) {
    const original=originals[operation.id];
    handlers['admit_'+operation.id]=async context=>{
      let selected;try{selected=request(operation.id,context);}catch{return failure(422,'ODATA_REQUEST_INVALID');}
      return typeof original.admit==='function'?original.admit(supplierContext(operation,context,selected)):true;
    };
    handlers['read_'+operation.id]=context=>{
      const promise=(async()=>{
        let selected;try{selected=request(operation.id,context);}catch{return failure(422,'ODATA_REQUEST_INVALID');}
        totals.supplierReads++;
        const response=await original(supplierContext(operation,context,selected));
        if(response.status!==200)return failure(response.status===429||response.status===503?response.status:502,'ODATA_SUPPLIER_REQUEST_FAILED');
        try {
          const contentType=(response.headers?.['content-type']??'').split(';')[0].trim().toLowerCase();
          if(contentType!=='application/json'&&!contentType.endsWith('+json'))throw new TypeError('OData JSON required');
          const native=parsePage({catalog,query:selected.compiled,raw:response.body,url:selected.url,headers:response.headers,status:response.status});
          const seenRows=selected.seenRows+native.rows.length;
          if(native.rows.length>operation.maxPageRows||seenRows>selected.query.top)throw new TypeError('Supplier exceeded the selected row ceiling');
          if(native.nextLink&&native.rows.length===0)throw new TypeError('Supplier continuation returned no rows');
          const completion=seenRows===selected.query.top?'limit':native.nextLink?'continue':'provider';
          const next=completion==='continue'?codec.encode({operation:operation.id,query:selected.query,seenRows,
            url:nextUrl(catalog,operation,native.nextLink,selected.url,selected.compiled.url,selected.query.top-seenRows)}):null;
          const page={schema:PAGE_SCHEMA,operation:operation.id,entitySet:operation.entitySet,metadataSha256:catalog.receipts.metadata.sha256,
            query:selected.query,queryFingerprint:selected.compiled.fingerprint,items:projectRows(native.rows,selected.query),
            count:native.count,seenRows,completion,next,supplierResponseSha256:native.source.sha256,
            receivedAt:native.source.receivedAt,etag:native.source.etag};
          validatePage(page,plan,catalog,operation.id);
          totals.deliveredPages++;totals.deliveredRows+=page.items.length;
          return {status:200,headers:{'content-type':'application/json; charset=utf-8'},body:page};
        }catch{totals.rejectedResponses++;return failure(502,'ODATA_SUPPLIER_RESPONSE_INVALID');}
      })();
      active.add(promise);promise.then(()=>active.delete(promise),()=>active.delete(promise));return promise;
    };
  }
  const close=()=>closing??=(async()=>{closed=true;await Promise.allSettled([...active]);await closeUpstreamHandlers(originals);})();
  return {...prepared,config:prepared.service,handlers:Object.freeze(handlers),close,
    snapshot:()=>({schema:'stellar-forge.odata-live-runtime.v1',closed,metadataSha256:catalog.receipts.metadata.sha256,
      operations:plan.operations.map(row=>row.id),...totals})};
}

// MIT. Portable live merchant package and original SF88 customer request/receiving.
import { constants } from 'node:fs';
import { open,mkdir,writeFile } from 'node:fs/promises';
import { join,resolve } from 'node:path';
import { randomUUID } from 'node:crypto';
import { prepareReview } from '../../../sf88-operator-buyer-cli/prepare.mjs';
import { compileQuery } from '../source.mjs';
import { prepareProduct,templatePlan,json } from './config.mjs';
import { buildQuery,digest,validatePage,plain } from './contract.mjs';
export async function readBytes(path,limit=16777216) {
  const handle=await open(path,constants.O_RDONLY|constants.O_NOFOLLOW);
  try {
    const info=await handle.stat();if(!info.isFile()||info.size>limit)throw new TypeError('Select a regular source file within its size limit');
    const content=await handle.readFile();if(content.length>limit)throw new TypeError('Source file grew beyond its size limit');return content;
  }finally{await handle.close();}
}
export async function readJson(path,limit) {return JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(await readBytes(path,limit)));}
export function prepareDraft({catalog,plan,selection},options={}) {
  const prepared=prepareProduct(plan,catalog,options);
  if(!plain(selection)||typeof selection.operation!=='string'||!plain(selection.request)||Object.keys(selection).some(key=>!['operation','request'].includes(key)))
    throw new TypeError('Choose one live merchant operation and its customer query');
  const query=buildQuery(prepared.plan,catalog,selection.operation,selection.request);
  return {...prepared,selection:{operation:selection.operation,request:query.query},query};
}
async function workspaceSelection(workspace,planId) {
  const state=await workspace.state(),retained=state.plans.find(row=>row.id===planId);
  if(!retained)throw new TypeError('Choose a saved original OData query');
  const connection=state.connections.find(row=>row.id===retained.connectionId);
  if(!connection||connection.catalogHash!==retained.catalogHash)throw new TypeError('The saved query belongs to a different metadata edition');
  const compiled=compileQuery(connection.catalog,retained.query.plan);
  if(compiled.fingerprint!==retained.query.fingerprint)throw new TypeError('The original saved query changed');
  return {connection,compiled};
}
function connectionPlan(plan,connection) {
  const selected=structuredClone(plan);
  if(connection.authEnv&&!selected.oauth2&&!Object.keys(selected.headerEnv??{}).some(name=>name.toLowerCase()==='authorization'))
    selected.headerEnv={...selected.headerEnv,authorization:connection.authEnv};
  return selected;
}
/** Start the operator form from the exact selected query and its source connection. */
export async function templateFromWorkspace(workspace,{planId,publicOrigin,payment,amountAtomic}={}) {
  const {connection,compiled}=await workspaceSelection(workspace,planId);
  const plan=templatePlan(connection.catalog,{entitySet:compiled.plan.entitySet,...(publicOrigin?{publicOrigin}:{})});
  const operation=plan.operations[0];
  operation.fields=[...compiled.plan.select];
  operation.filterFields=[...new Set(compiled.plan.filters.map(filter=>filter.field))];
  operation.sourceFilters=structuredClone(compiled.plan.filters);
  operation.sourceFilterMode=compiled.plan.filterMode;
  operation.orderFields=compiled.plan.orderBy.map(order=>order.field);
  operation.maxPageRows=Math.max(1000,compiled.plan.pageSize);
  operation.maxTotalRows=Math.max(1,compiled.plan.top??100000);
  if(payment)plan.payment=structuredClone(payment);
  if(amountAtomic!==undefined)operation.amountAtomic=amountAtomic;
  return connectionPlan(plan,connection);
}
/** Consume the original retained operator workspace without a second project store. */
export async function prepareFromWorkspace(workspace,{planId,plan,operation}={},options={}) {
  const {connection,compiled}=await workspaceSelection(workspace,planId);
  plan=connectionPlan(plan,connection);
  const catalog=structuredClone(connection.catalog);
  for(const receipt of Object.values(catalog.receipts)) {
    const bytes=receipt.rawBase64?Buffer.from(receipt.rawBase64,'base64'):await workspace.raw(receipt.sha256);
    if(digest(bytes)!==receipt.sha256)throw new TypeError('Original catalog source identity changed');
    receipt.rawBase64=bytes.toString('base64');
  }
  const {entitySet,...request}=compiled.plan;
  const id=operation??plan.operations.find(row=>row.entitySet===entitySet||row.entitySet===compiled.entitySet)?.id;
  return prepareDraft({catalog,plan,selection:{operation:id,request}},options);
}
export async function writePackage(prepared,directory) {
  const root=resolve(directory);await mkdir(root,{mode:0o700});
  const files={'catalog.json':json(prepared.catalog),'plan.json':json(prepared.plan),
    'seller-service.json':json(prepared.service),'offers.json':json(prepared.offers),'openapi.json':json(prepared.spec),
    'customer-query.json':json(prepared.selection),'request.json':json(prepared.selection.request)};
  for(const [name,content]of Object.entries(files))await writeFile(join(root,name),content,{flag:'wx',mode:0o600});
  const manifest={schema:'stellar-forge.odata-live-package.v1',id:randomUUID(),createdAt:new Date().toISOString(),
    sourceBinding:prepared.sourceBinding,files:Object.fromEntries(Object.entries(files).map(([name,content])=>[name,{bytes:Buffer.byteLength(content),sha256:digest(content)}]))};
  await writeFile(join(root,'package.json'),json(manifest),{flag:'wx',mode:0o600});return {directory:root,...manifest};
}
export async function readPackage(directory,options={}) {
  const root=resolve(directory),manifest=await readJson(join(root,'package.json'),65536);
  const required=['catalog.json','plan.json','seller-service.json','offers.json','openapi.json','customer-query.json','request.json'];
  if(manifest.schema!=='stellar-forge.odata-live-package.v1'||!plain(manifest.files)||Object.keys(manifest.files).length!==required.length||
      required.some(name=>!Object.hasOwn(manifest.files,name)))throw new TypeError('Original complete live OData package required');
  const loaded={};
  for(const name of required){const content=await readBytes(join(root,name));
    if(content.length!==manifest.files[name].bytes||digest(content)!==manifest.files[name].sha256)throw new TypeError('Live OData package changed: '+name);
    loaded[name]=new TextDecoder('utf-8',{fatal:true}).decode(content);}
  const prepared=prepareDraft({catalog:JSON.parse(loaded['catalog.json']),plan:JSON.parse(loaded['plan.json']),selection:JSON.parse(loaded['customer-query.json'])},options);
  if(prepared.sourceBinding!==manifest.sourceBinding||json(prepared.service)!==loaded['seller-service.json']||
      json(prepared.offers)!==loaded['offers.json']||json(prepared.spec)!==loaded['openapi.json']||json(prepared.selection.request)!==loaded['request.json'])
    throw new TypeError('Original OData compiler and selected package disagree');
