    need(value!==null&&value!==undefined,'KEY','Every row needs its complete declared non-null key.');
    if(type==='Edm.Guid'){
      need(typeof value==='string'&&/^[a-f0-9]{8}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{4}-[a-f0-9]{12}$/i.test(value),
