   if(['INTERRUPTED','FAILED','CANCELLED'].includes(saved.state)){try{return await publisher.recover(runId);}catch(e){return {...saved,recoveryError:e.code??'ORIGINAL_RECOVERY_FAILED'};}}
   return saved;
  }
