    const inputSchema = offer.extensions.bazaar.schema.properties.input;
    const key = isQuery ? 'queryParams' : 'body';
    input[key] = example;
    inputSchema.properties[key] = { type: 'object', properties: Object.fromEntries(parameters.map(parameter =>
