const PACKAGE_NAME = '@tokenjunkielabs/starforge-merchant';
const BASE = 'stellar/scf-starforge-20261009/sf46-release/';
const SHA = /^[0-9a-f]{64}$/;
const PIN = /^\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?$/;
