  catch (error) { if (error.code !== 'ENOENT') throw error; }
  try { await lstat(descriptorPath); fail('CONTROL_DESCRIPTOR_ALREADY_EXISTS'); }
  catch (error) { if (error.code !== 'ENOENT') throw error; }
