    .replace('<title>Stellar Forge · Captured API review</title>', '<title>Stellar Forge · Capture refresh review</title>')
    .replace('<h1>Captured API review</h1>', '<h1>Capture refresh review</h1>')
    .replace('<main>', () => '<main>' + section)
