    const buffer = Buffer.alloc(Math.min(delivery.bytes, PREVIEW_BYTES));
    let position = 0;
    while (position < buffer.length) {
      const { bytesRead } = await handle.read(buffer, position, buffer.length - position, position);
      if (!bytesRead) break;
      position += bytesRead;
