      saved?.status === 'FAILED' ? 'FAILED' : active ? (live?.bytes > 0 ? 'CAPTURING' : 'AWAITING_RESPONSE') :
      job.state === 'QUEUED' ? 'PREPARED' : job.state === 'CANCELLED' ? 'CANCELLED' :
      job.outcome ? 'NO_CAPTURE' : 'RECOVERY_REQUIRED';
