import { operatorApprovalEnvironment, checkBrowserApprovalChannel,
  requestBrowserReview, finishBrowserReview } from './browser-approval.mjs';
export { createBrowserApprovalBroker, operatorApprovalEnvironment } from './browser-approval.mjs';

const helper = fileURLToPath(new URL('./approve.py', import.meta.url));
const sha256 = bytes => createHash('sha256').update(bytes).digest('hex');
const keys = ['SF36_CONSENT_KEY_B64', 'SF36_AUDIT_KEY_B64', 'SF36_OPERATOR_KEY_B64'];
let terminalBusy = false;

/** Versioned wire formats implemented by this bridge and its paired helper. */
export const OPERATOR_APPROVAL_CAPABILITIES = Object.freeze({
  schema: 'stellar-forge.sf81.capabilities.v1',
  review_channels: Object.freeze(['terminal', 'pipe']),
  review_schema: 'stellar-forge.sf81.review.v1',
  decision_schema: 'stellar-forge.sf81.decision.v1',
  approval_schema: 'stellar-forge.sf81.approval.v1',
  operator_review_schema: 'stellar-forge.sf62.operator-review.v1',
});

/**
 * Query this imported module's own helper with the same trusted Python selected
 * for createOperatorApproval. Other operator fields are deliberately unused.
 * Import the bridge from the original retained runtime before calling this
 * probe; it does not select or relocate a foreign helper or accounting runtime.
 * A supported result describes the pipe protocol. checkOperatorChannel checks
 * the owning host's live transport separately.
 */
export async function probeOperatorApprovalCapabilities({ python } = {},
  { timeoutMs = 3000, signal } = {}) {
  if (typeof python !== 'string' || !isAbsolute(python) || python.includes('\0'))
    throw new TypeError('python must be the trusted absolute interpreter path');
  if (!Number.isSafeInteger(timeoutMs) || timeoutMs < 100 || timeoutMs > 30_000)
    throw new TypeError('capability timeout must be 100..30000 milliseconds');
  if (signal !== undefined && !(signal instanceof AbortSignal))
    throw new TypeError('signal must be an AbortSignal');
  const selection = Object.freeze({ python, helper });
  const result = (code, capabilities = null) => Object.freeze({
    schema: 'stellar-forge.sf81.capability-probe.v1',
    supported: code === 'OPERATOR_BROWSER_REVIEW_SUPPORTED',
    code, selection, capabilities,
  });
  if (signal?.aborted) return result('OPERATOR_CAPABILITIES_ABORTED');
  return await new Promise(resolve => {
    let child, timer, killTimer, failure, done = false, output = Buffer.alloc(0);
    const finish = (code, capabilities) => {
      if (done) return;
      done = true; clearTimeout(timer); clearTimeout(killTimer);
      signal?.removeEventListener('abort', abort);
      resolve(result(code, capabilities));
    };
    const stop = code => {
      if (done) return;
      failure ??= code;
      if (child && child.exitCode === null && child.signalCode === null) {
        child.kill('SIGTERM');
        killTimer ??= setTimeout(() => child.kill('SIGKILL'), 1000);
        killTimer.unref();
      }
    };
    const abort = () => stop('OPERATOR_CAPABILITIES_ABORTED');
    try {
      child = spawn(python, ['-I', '-B', '-u', helper, '--capabilities'], {
        env: { LANG: 'C.UTF-8', LC_ALL: 'C.UTF-8' },
        shell: false, windowsHide: true, stdio: ['ignore', 'pipe', 'ignore'],
      });
    } catch { finish('OPERATOR_CAPABILITIES_UNAVAILABLE'); return; }
    child.once('error', () => finish('OPERATOR_CAPABILITIES_UNAVAILABLE'));
    child.stdout.on('error', () => stop('OPERATOR_CAPABILITIES_UNAVAILABLE'));
    child.stdout.on('data', chunk => {
      if (done || failure) return;
      if (output.length + chunk.length > 8192) {
        stop('OPERATOR_CAPABILITIES_INVALID'); return;
      }
      output = Buffer.concat([output, chunk]);
    });
    child.once('close', (exitCode, childSignal) => {
      if (failure) { finish(failure); return; }
      // An original helper without the query rejects these arguments in its
      // parser before it can read stdin or enter the original approval flow.
      if (exitCode === 2 && !childSignal && output.toString('utf8').trim() === '') {
        finish('OPERATOR_CAPABILITIES_UNSUPPORTED'); return;
      }
      if (exitCode !== 0 || childSignal) {
        finish('OPERATOR_CAPABILITIES_UNAVAILABLE'); return;
      }
      let advertised;
      try { advertised = JSON.parse(new TextDecoder('utf-8', { fatal: true }).decode(output)); }
      catch { finish('OPERATOR_CAPABILITIES_INVALID'); return; }
      const expected = OPERATOR_APPROVAL_CAPABILITIES;
      if (!advertised || typeof advertised !== 'object' || Array.isArray(advertised) ||
          !Array.isArray(advertised.review_channels) ||
          !expected.review_channels.every(channel => advertised.review_channels.includes(channel)) ||
          !Object.entries(expected).every(([key, value]) =>
            key === 'review_channels' || advertised[key] === value)) {
        finish('OPERATOR_CAPABILITIES_UNSUPPORTED'); return;
      }
      finish('OPERATOR_BROWSER_REVIEW_SUPPORTED', expected);
    });
    timer = setTimeout(() => stop('OPERATOR_CAPABILITIES_TIMEOUT'), timeoutMs);
    signal?.addEventListener('abort', abort, { once: true });
    if (signal?.aborted) abort();
  });
}

export class OperatorBridgeError extends Error {
  constructor(code, intentId) {
    super(code); this.name = 'OperatorBridgeError'; this.code = code;
    this.intentId = intentId;
    this.reservationState = 'CHECK_NATIVE_LEDGER_DO_NOT_RELEASE_OR_RETRY';
    this.paymentSent = false;
  }
}

/** Check the actual approval device without reading input or requesting consent. */
export async function checkOperatorTerminal(intentId) {
  try {
    // A tool may allocate a TTY stream without making it the controlling TTY.
    // SF62 opens this same device, independent of the subprocess stdin pipe.
    const terminal = await open('/dev/tty', constants.O_RDWR | (constants.O_NOCTTY ?? 0));
    try {
      if (!(await terminal.stat()).isCharacterDevice()) throw new Error('not a terminal');
    } finally { await terminal.close(); }
  } catch {
    throw new OperatorBridgeError('OPERATOR_CONTROLLING_TERMINAL_REQUIRED', intentId);
  }
}

/** Resolve the host-selected channel; a failed browser selection never falls back. */
export async function checkOperatorChannel(intentId, { environment = process.env } = {}) {
  try {
    const selected = operatorApprovalEnvironment(environment);
    if (Object.keys(selected).length) await checkBrowserApprovalChannel(selected);
    else await checkOperatorTerminal(intentId);
  } catch (error) {
    if (error instanceof OperatorBridgeError) throw error;
    throw new OperatorBridgeError(error.code ?? 'OPERATOR_CHANNEL_UNAVAILABLE', intentId);
  }
}

/** Construction is privileged configuration, never values supplied by a seller/agent. */
export function createOperatorApproval({ python, actor, service, policy, ledger,
  environment = process.env, timeoutMs = 300_000 } = {}) {
  for (const path of [python, policy, ledger])
    if (typeof path !== 'string' || !isAbsolute(path) || path.includes('\0'))
      throw new TypeError('python, policy and ledger must be trusted absolute paths');
  for (const id of [actor, service])
    if (typeof id !== 'string' || !/^[A-Za-z0-9._:-]{1,160}$/.test(id))
      throw new TypeError('verified actor and service IDs are required');
  if (!Number.isSafeInteger(timeoutMs) || timeoutMs < 100 || timeoutMs > 900_000)
    throw new TypeError('approval timeout must be 100..900000 milliseconds');
  const browserEnvironment = operatorApprovalEnvironment(environment);
  const browser = Object.keys(browserEnvironment).length > 0;
  // Python receives only the existing native accounting keys, not transport tokens.
  const env = { LANG: 'C.UTF-8', LC_ALL: 'C.UTF-8' };
  for (const name of keys) {
    const value = environment[name];
    if (typeof value !== 'string' || value.length > 4096)
      throw new TypeError('existing SF36 operator keys are required');
    env[name] = value;
  }
  const resumeFile = environment.SF36_EXPIRED_RESUME_FILE;
  if (resumeFile !== undefined) {
    if (typeof resumeFile !== 'string' || !isAbsolute(resumeFile) ||
        resumeFile.includes('\0') || resumeFile.length > 4096)
      throw new TypeError('expired authorization resume must select a private absolute permit file');
    // The fixed Python helper authenticates this host-selected private file.
    // Its token and all unrelated parent environment stay outside the wire.
    env.SF36_EXPIRED_RESUME_FILE = resumeFile;
  }
  const args = ['-I', '-B', '-u', helper, '--actor', actor, '--service', service,
    '--policy', policy, '--ledger', ledger,
    ...(browser ? ['--review-channel', 'pipe'] : [])];
  return async function approve(intent, { signal } = {}) {
    const fail = code => new OperatorBridgeError(code, intent?.intentId);
    if (signal !== undefined && !(signal instanceof AbortSignal))
      throw new TypeError('signal must be an AbortSignal');
    if (signal?.aborted) throw fail('OPERATOR_ABORTED');
    if (terminalBusy) throw fail('OPERATOR_BUSY');
    const raw = Buffer.from(JSON.stringify(intent), 'utf8');
    if (raw.length > 65_536) throw fail('OPERATOR_INTENT_TOO_LARGE');
    const digest = sha256(raw);
    terminalBusy = true;
    try {
      await checkOperatorChannel(intent?.intentId, { environment: browserEnvironment });
      if (signal?.aborted) throw fail('OPERATOR_ABORTED');
      return await new Promise((resolve, reject) => {
        const deadline = Date.now() + timeoutMs;
        let child, timer, killTimer, failure, done = false;
        let buffered = Buffer.alloc(0), finalRecord, reviewSeen = false, decision;
        const transport = new AbortController();
        const finish = (error, value) => {
          if (done) return; done = true;
          clearTimeout(timer); clearTimeout(killTimer);
          signal?.removeEventListener('abort', abort);
          transport.abort();
          error ? reject(error) : resolve(value);
        };
        const stop = code => {
          if (done) return;
          failure ??= fail(code);
          transport.abort();
          if (child && child.exitCode === null && child.signalCode === null) {
            child.kill('SIGTERM');
            killTimer ??= setTimeout(() => child.kill('SIGKILL'), 1000);
            killTimer.unref();
          }
        };
        const abort = () => stop('OPERATOR_ABORTED');
        const receive = frame => {
          let record;
          try { record = JSON.parse(frame); } catch { stop('OPERATOR_INVALID_RESULT'); return; }
          if (browser && record?.schema === 'stellar-forge.sf81.review.v1') {
            const r = record.review;
            if (reviewSeen || finalRecord || record.input_sha256 !== digest ||
                r?.request_id !== intent.intentId || r.max_atomic_units_to_reserve !== intent.amount ||
                r.network !== intent.network || r.asset !== intent.asset ||
                !/^[0-9a-f]{64}$/.test(r.request_sha256 ?? '') ||
                record.current_native_budget_estimate?.approved !== true) {
              stop('OPERATOR_REVIEW_MISMATCH'); return;
            }
            reviewSeen = true;
            const remaining = deadline - Date.now();
            if (remaining < 100) { stop('OPERATOR_TIMEOUT'); return; }
            void requestBrowserReview(browserEnvironment, record,
              { signal: transport.signal, timeoutMs: remaining }).then(answer => {
              if (done || failure || signal?.aborted) return;
              decision = answer;
              child.stdin.end(JSON.stringify({
                schema: 'stellar-forge.sf81.decision.v1',
                input_sha256: digest, request_sha256: answer.requestSha256,
                decision: answer.decision,
              }) + '\n');
            }, error => stop(error.code ?? 'OPERATOR_BROWSER_REVIEW_FAILED'));
            return;
          }
          if (frame.length > 8192 || finalRecord ||
              record?.schema !== 'stellar-forge.sf81.approval.v1' ||
              browser && record.reservation && (!decision || decision.decision !== 'approve')) {
            stop('OPERATOR_INVALID_RESULT'); return;
          }
          finalRecord = record;
        };
        try {
          child = spawn(python, args, { env, shell: false, windowsHide: true,
            stdio: ['pipe', 'pipe', 'ignore'] });
        } catch { finish(fail('OPERATOR_START_FAILED')); return; }
        child.once('error', () => finish(fail('OPERATOR_START_FAILED')));
        child.stdout.on('data', chunk => {
          buffered = Buffer.concat([buffered, chunk]);
          if (buffered.length > (browser ? 512 * 1024 : 8192)) {
            stop('OPERATOR_RESULT_TOO_LARGE'); return;
          }
          let end;
          while ((end = buffered.indexOf(10)) >= 0) {
            const frame = buffered.subarray(0, end);
            buffered = buffered.subarray(end + 1);
            if (frame.length) receive(frame);
          }
        });
        child.stdin.on('error', () => stop('OPERATOR_INPUT_FAILED'));
        child.once('close', async (code, childSignal) => {
          if (buffered.length) receive(buffered);
          let error = failure;
          if (!error && (code !== 0 || childSignal)) {
            error = fail('OPERATOR_NO_APPROVAL');
            if (typeof finalRecord?.reason === 'string' && finalRecord.reason.length <= 256)
              error.operatorReason = finalRecord.reason;
          }
          const r = finalRecord?.reservation;
          if (!error && (finalRecord?.schema !== 'stellar-forge.sf81.approval.v1' ||
              finalRecord.input_sha256 !== digest || r?.schema !== 'stellar-forge.sf62.result.v1' ||
              r.outcome !== 'FRESH_RESERVATION_APPROVED' || r.request_id !== intent.intentId ||
              r.reserved_atomic_units !== intent.amount || r.network !== intent.network ||
              r.asset !== intent.asset || !/^[0-9a-f]{64}$/.test(r.request_sha256 ?? '') ||
              browser && r.request_sha256 !== decision?.requestSha256 ||
              r.signed_requests !== 0 || r.wallet_calls !== 0 || r.payments_confirmed !== 0))
            error = fail('OPERATOR_RESERVATION_MISMATCH');
          if (signal?.aborted) error ??= fail('OPERATOR_ABORTED');
          if (browser && decision) {
            try { await finishBrowserReview(browserEnvironment, decision, error ? 'FAILED' : 'APPROVED'); }
            catch (reportError) { error ??= fail(reportError.code ?? 'OPERATOR_BROWSER_RESULT_UNCONFIRMED'); }
          }
          error ??= failure;
          if (signal?.aborted) error ??= fail('OPERATOR_ABORTED');
          finish(error, error ? undefined : Object.freeze({ ...r, input_sha256: digest }));
        });
        timer = setTimeout(() => stop('OPERATOR_TIMEOUT'), Math.max(1, deadline - Date.now()));
        signal?.addEventListener('abort', abort, { once: true });
        if (signal?.aborted) abort();
        if (browser) child.stdin.write(Buffer.concat([raw, Buffer.from('\n')]));
        else child.stdin.end(raw);
      });
    } finally { terminalBusy = false; }
  };
}

/** One stable operation ID, original wire client, original signer, no blind retries. */
export class OperatorApprovedBuyer {
  #buyer; #approve;
  constructor({ operator, fetchImpl = createPublicHttpsFetch() } = {}) {
    this.#buyer = new X402BuyerClient({ fetchImpl });
    this.#approve = createOperatorApproval(operator);
  }
  discover(options) { return this.#buyer.discover(options); }
  async call(options = {}) {
    if ('approve' in options) throw new TypeError('operator approval cannot be replaced per call');
    const { sign, signal, intentId } = options;
    if (typeof sign !== 'function' || typeof intentId !== 'string' ||
        !/^[A-Za-z0-9._:-]{1,160}$/.test(intentId))
      throw new TypeError('original signer and stable intentId required');
    let reservation = null;
    const checkAbort = () => {
      if (signal?.aborted) throw new OperatorBridgeError('OPERATOR_ABORTED', intentId);
    };
    checkAbort();
    try {
      const result = await this.#buyer.call({ ...options,
        approve: async intent => {
          reservation = await this.#approve(intent, { signal });
          checkAbort(); return true;
        },
        sign: async payload => {
          checkAbort();
          const signed = await sign(payload);
          checkAbort(); return signed;
        },
      });
      return { ...result, operatorReservation: reservation };
    } catch (error) {
      // Preserve original SF31 paymentSent/unknown-outcome semantics unchanged.
      if (error && typeof error === 'object' && Object.isExtensible(error))
        error.operatorReservation = reservation;
      throw error;
    }
  }
}

// MIT. Host-owned local review transport; original SF62/SF36 owns reservations.
import { createServer, createConnection } from 'node:net';
import { randomBytes, randomUUID, timingSafeEqual } from 'node:crypto';
import { chmod, lstat, mkdtemp, rmdir } from 'node:fs/promises';
import { isAbsolute, join } from 'node:path';
import { tmpdir } from 'node:os';

const SOCKET = 'SF81_APPROVAL_SOCKET', TOKEN = 'SF81_APPROVAL_TOKEN';
const SCHEMA = 'stellar-forge.sf81.browser-channel.v1';
const MAX_FRAME = 512 * 1024;
const HASH = /^[a-f0-9]{64}$/;
const ID = /^[A-Za-z0-9._:-]{1,160}$/;
const object = value => value !== null && typeof value === 'object' && !Array.isArray(value);
const failure = (code, status = 409) => Object.assign(new Error(code), { code, status });

/** Copy only the trusted host's ephemeral transport, never keys or seller data. */
export function operatorApprovalEnvironment(environment = process.env) {
  const path = environment[SOCKET], token = environment[TOKEN];
  if (path === undefined && token === undefined) return {};
  if (typeof path !== 'string' || !isAbsolute(path) || path.includes('\0') ||
      Buffer.byteLength(path) > 103 || !HASH.test(token ?? ''))
    throw failure('OPERATOR_BROWSER_CHANNEL_CONFIGURATION_INVALID');
  return { [SOCKET]: path, [TOKEN]: token };
}

async function privateSocket(path) {
  let info;
  try { info = await lstat(path); } catch { throw failure('OPERATOR_BROWSER_CHANNEL_UNAVAILABLE'); }
  if (!info.isSocket() || (info.mode & 0o077) ||
      typeof process.getuid === 'function' && info.uid !== process.getuid())
    throw failure('OPERATOR_BROWSER_CHANNEL_NOT_PRIVATE');
}

async function exchange(environment, message, { signal, timeoutMs = 5000 } = {}) {
  const selected = operatorApprovalEnvironment(environment);
  if (!selected[SOCKET]) throw failure('OPERATOR_BROWSER_CHANNEL_REQUIRED');
  if (signal?.aborted) throw failure('OPERATOR_ABORTED');
  await privateSocket(selected[SOCKET]);
  const raw = Buffer.from(JSON.stringify({ schema: SCHEMA, token: selected[TOKEN], ...message }) + '\n');
  if (raw.length > MAX_FRAME) throw failure('OPERATOR_BROWSER_FRAME_TOO_LARGE');
  return new Promise((resolve, reject) => {
    let buffer = Buffer.alloc(0), done = false;
    const socket = createConnection(selected[SOCKET]);
    const finish = (error, value) => {
      if (done) return; done = true;
      clearTimeout(timer); signal?.removeEventListener('abort', abort);
      socket.destroy(); error ? reject(error) : resolve(value);
    };
    const abort = () => finish(failure('OPERATOR_ABORTED'));
    const timer = setTimeout(() => finish(failure('OPERATOR_BROWSER_CHANNEL_TIMEOUT')), timeoutMs);
    socket.once('connect', () => socket.write(raw));
    socket.on('error', () => finish(failure('OPERATOR_BROWSER_CHANNEL_UNAVAILABLE')));
    socket.once('close', () => finish(failure('OPERATOR_BROWSER_CHANNEL_CLOSED')));
    socket.on('data', chunk => {
      buffer = Buffer.concat([buffer, chunk]);
      if (buffer.length > MAX_FRAME) return finish(failure('OPERATOR_BROWSER_FRAME_TOO_LARGE'));
      const end = buffer.indexOf(10);
      if (end < 0) return;
      if (end !== buffer.length - 1) return finish(failure('OPERATOR_BROWSER_RESPONSE_INVALID'));
      let result;
      try { result = JSON.parse(buffer.subarray(0, end)); } catch { return finish(failure('OPERATOR_BROWSER_RESPONSE_INVALID')); }
      if (result?.schema !== SCHEMA || typeof result.ok !== 'boolean')
        return finish(failure('OPERATOR_BROWSER_RESPONSE_INVALID'));
      if (!result.ok) return finish(failure(typeof result.error === 'string' ? result.error : 'OPERATOR_BROWSER_REVIEW_FAILED'));
      finish(null, result);
    });
    signal?.addEventListener('abort', abort, { once: true });
    if (signal?.aborted) abort();
  });
}

export async function checkBrowserApprovalChannel(environment) {
  await exchange(environment, { type: 'ping' });
}

export async function requestBrowserReview(environment, record, { signal, timeoutMs = 300000 } = {}) {
  const result = await exchange(environment, { type: 'review', record, timeoutMs },
    { signal, timeoutMs: timeoutMs + 1000 });
  if (!ID.test(result.approvalId ?? '') || !['approve', 'reject'].includes(result.decision) ||
      result.inputSha256 !== record.input_sha256 || result.requestSha256 !== record.review.request_sha256)
    throw failure('OPERATOR_BROWSER_DECISION_MISMATCH');
  return result;
}

export async function finishBrowserReview(environment, decision, state) {
  if (!['APPROVED', 'FAILED'].includes(state)) throw failure('OPERATOR_BROWSER_RESULT_INVALID');
  await exchange(environment, { type: 'result', approvalId: decision.approvalId,
    requestSha256: decision.requestSha256, inputSha256: decision.inputSha256, state });
}

/** One owned broker per operator console; the browser token remains with its HTTP host. */
export async function createBrowserApprovalBroker({ directory = tmpdir() } = {}) {
  if (typeof directory !== 'string' || !isAbsolute(directory)) throw new TypeError('Absolute host directory required');
  if (Buffer.byteLength(join(directory, 'sf81-XXXXXX', 'review.sock')) > 103)
    throw new TypeError('Host socket directory is too long');
  const owned = await mkdtemp(join(directory, 'sf81-'));
  const path = join(owned, 'review.sock'), token = randomBytes(32).toString('hex');
  const environment = Object.freeze(operatorApprovalEnvironment({ [SOCKET]: path, [TOKEN]: token }));
  const secret = Buffer.from(token), records = new Map(), sockets = new Set();
  let closed = false, closing;
  const view = entry => entry ? structuredClone(entry.public) : null;
  const send = (socket, value) => {
    if (!socket.destroyed) socket.end(JSON.stringify({ schema: SCHEMA, ...value }) + '\n');
  };
  const retire = (entry, state, code) => {
    if (!['AWAITING_OPERATOR', 'APPROVING'].includes(entry.public.state)) return;
    clearTimeout(entry.timer); entry.public.state = state;
    entry.public.completedAt = new Date().toISOString();
    send(entry.socket, { ok: false, error: code });
  };
  const forIntent = intent => [...records.values()].reverse().find(entry => entry.public.intentId === intent);
  const server = createServer(socket => {
    sockets.add(socket);
    let buffer = Buffer.alloc(0), consumed = false, entry;
    const parseTimer = setTimeout(() => socket.destroy(), 5000);
    socket.on('error', () => {});
    socket.once('close', () => {
      clearTimeout(parseTimer); sockets.delete(socket);
      if (entry?.public.state === 'AWAITING_OPERATOR') {
        clearTimeout(entry.timer); entry.public.state = 'FAILED';
        entry.public.completedAt = new Date().toISOString();
      }
    });
    socket.on('data', chunk => {
      if (consumed) { socket.destroy(); return; }
      buffer = Buffer.concat([buffer, chunk]);
      if (buffer.length > MAX_FRAME) { socket.destroy(); return; }
      const end = buffer.indexOf(10);
      if (end < 0) return;
      consumed = true; clearTimeout(parseTimer);
      try {
        if (closed || end !== buffer.length - 1) throw failure('OPERATOR_BROWSER_REQUEST_INVALID');
        const message = JSON.parse(buffer.subarray(0, end));
        const supplied = Buffer.from(typeof message?.token === 'string' ? message.token : '');
        if (message?.schema !== SCHEMA || supplied.length !== secret.length || !timingSafeEqual(supplied, secret))
          throw failure('OPERATOR_BROWSER_CHANNEL_UNAUTHORIZED');
        if (message.type === 'ping') { send(socket, { ok: true }); return; }
        if (message.type === 'result') {
          const original = records.get(message.approvalId);
          if (!original || message.requestSha256 !== original.public.review.request_sha256 ||
              message.inputSha256 !== original.inputSha256 || !['APPROVED', 'FAILED'].includes(message.state))
            throw failure('OPERATOR_BROWSER_RESULT_MISMATCH');
          if (original.public.state === 'APPROVING') {
            original.public.state = message.state;
            original.public.completedAt = new Date().toISOString();
          } else if (original.public.state !== message.state && message.state !== 'FAILED') {
            throw failure('OPERATOR_BROWSER_RESULT_STATE_MISMATCH');
          }
          send(socket, { ok: true }); return;
        }
        if (message.type !== 'review') throw failure('OPERATOR_BROWSER_REQUEST_INVALID');
        const record = message.record, review = record?.review;
        const timeoutMs = message.timeoutMs;
        if (record?.schema !== 'stellar-forge.sf81.review.v1' || !HASH.test(record.input_sha256 ?? '') ||
            review?.schema !== 'stellar-forge.sf62.operator-review.v1' || !ID.test(review.request_id ?? '') ||
            !HASH.test(review.request_sha256 ?? '') || !object(review.complete_original_accepted_terms) ||
            !object(record.current_native_budget_estimate) || record.current_native_budget_estimate.approved !== true ||
            !Number.isSafeInteger(timeoutMs) || timeoutMs < 100 || timeoutMs > 900000)
          throw failure('OPERATOR_BROWSER_REVIEW_INVALID');
        const previous = forIntent(review.request_id);
        // Original consumers may re-enter an unpaid dataset page only after
        // their authenticated absence check. The native ledger still decides
        // fresh reservation; retain each failed/rejected review independently.
        if (previous && ['AWAITING_OPERATOR', 'APPROVING', 'APPROVED'].includes(previous.public.state))
          throw failure('OPERATOR_BROWSER_INTENT_ALREADY_REVIEWED');
        if (records.size >= 256) {
          const old = [...records.values()].find(item => !['AWAITING_OPERATOR', 'APPROVING'].includes(item.public.state));
          if (!old) throw failure('OPERATOR_BROWSER_BUSY');
          records.delete(old.public.id);
        }
        const now = Date.now();
        entry = { socket, inputSha256: record.input_sha256, public: {
          id: randomUUID(), intentId: review.request_id, state: 'AWAITING_OPERATOR',
          createdAt: new Date(now).toISOString(), expiresAt: new Date(now + timeoutMs).toISOString(),
          review, current_native_budget_estimate: record.current_native_budget_estimate,
        } };
        entry.timer = setTimeout(() => retire(entry, 'EXPIRED', 'OPERATOR_BROWSER_REVIEW_EXPIRED'), timeoutMs);
        records.set(entry.public.id, entry);
      } catch (error) { send(socket, { ok: false, error: error.code ?? 'OPERATOR_BROWSER_REQUEST_INVALID' }); }
    });
  });
  try {
    await chmod(owned, 0o700);
    await new Promise((resolve, reject) => {
      server.once('error', reject); server.listen(path, resolve);
    });
    await chmod(path, 0o600);
  } catch (error) {
    server.close(); await rmdir(owned).catch(() => {}); throw error;
  }
  return Object.freeze({ environment,
    snapshot(intentId) { return view(forIntent(intentId)); },
    decide({ intent, approvalId, requestSha256, decision } = {}) {
      const entry = records.get(approvalId);
      if (closed || !entry || entry.public.intentId !== intent ||
          entry.public.review.request_sha256 !== requestSha256 || !['approve', 'reject'].includes(decision))
        throw failure('OPERATOR_BROWSER_DECISION_MISMATCH');
      if (entry.decision === decision && ['APPROVING', 'APPROVED', 'REJECTED'].includes(entry.public.state)) return view(entry);
      if (entry.public.state !== 'AWAITING_OPERATOR') throw failure('OPERATOR_BROWSER_REVIEW_NO_LONGER_PENDING');
      if (Date.now() >= Date.parse(entry.public.expiresAt)) {
        retire(entry, 'EXPIRED', 'OPERATOR_BROWSER_REVIEW_EXPIRED');
        throw failure('OPERATOR_BROWSER_REVIEW_EXPIRED');
      }
      if (entry.socket.destroyed) {
        retire(entry, 'FAILED', 'OPERATOR_BROWSER_CHANNEL_CLOSED');
        throw failure('OPERATOR_BROWSER_CHANNEL_CLOSED');
      }
      clearTimeout(entry.timer); entry.decision = decision;
      entry.public.state = decision === 'approve' ? 'APPROVING' : 'REJECTED';
      entry.public.decidedAt = new Date().toISOString();
      send(entry.socket, { ok: true, approvalId, decision, requestSha256, inputSha256: entry.inputSha256 });
      return view(entry);
    },
    revoke(intentId) {
      const entry = forIntent(intentId);
      if (entry) retire(entry, 'FAILED', 'OPERATOR_ABORTED');
    },
    close() {
      return closing ??= (async () => {
        closed = true;
        for (const entry of records.values()) retire(entry, 'FAILED', 'OPERATOR_BROWSER_CHANNEL_CLOSED');
        for (const socket of sockets) socket.destroy();
        await new Promise((resolve, reject) => server.close(error => error ? reject(error) : resolve()));
        await rmdir(owned);
      })();
    },
  });
}

// MIT. Export payment-specific fields from an actual SF81 call, never Response body or signing keys.
const id = v => typeof v === 'string' && /^[A-Za-z0-9._:-]{1,160}$/.test(v);
const approvedFields = ['request_id','actor','service','network','asset','scheme','max_amount',
  'resource','pay_to','max_timeout_seconds','method','body_present','body_bytes',
  'body_sha256','accepted_terms_sha256'];
export function sf81ReconciliationRecord(result) {
  if (!result || !id(result.intentId) || result.attempts !== 2 ||
      !result.requirement || !result.receipt || !result.operatorReservation ||
      !['REPORTED_SUCCESS', 'PENDING'].includes(result.settlement)) {
    throw new TypeError('original paid SF81 result with receipt and reservation required');
  }
  const { requirement: q, receipt: r, operatorReservation: p } = result;
  if (p.schema !== 'stellar-forge.sf62.result.v1' ||
      p.outcome !== 'FRESH_RESERVATION_APPROVED' || p.request_id !== result.intentId ||
      p.network !== q.network || p.asset !== q.asset ||
      p.reserved_atomic_units !== q.amount || r.network !== q.network) {
    throw new TypeError('original SF81 operator reservation/receipt mismatch');
  }
  return {
    intentId: result.intentId,
    requirement: { scheme: q.scheme, network: q.network, asset: q.asset,
      payTo: q.payTo, amount: q.amount },
    receipt: { network: r.network, transaction: r.transaction, payer: r.payer,
      success: r.success, ...(r.amount === undefined ? {} : { amount: r.amount }),
      ...(r.errorReason === undefined ? {} : { errorReason: r.errorReason }) },
    operatorReservation: { schema: p.schema, outcome: p.outcome,
      request_id: p.request_id, network: p.network, asset: p.asset,
      ...(p.request_sha256 === undefined ? {} : {request_sha256:p.request_sha256}),
      ...(p.approved_request === undefined ? {} :
        {approved_request:Object.fromEntries(approvedFields.map(key=>[key,p.approved_request[key]]))}),
      reserved_atomic_units: p.reserved_atomic_units },
  };
}

// MIT. Atomic private records for the original SF82 checkout and its recovery.
import {constants} from 'node:fs';
import {open,lstat,link,unlink,readdir} from 'node:fs/promises';
import {dirname,join,isAbsolute} from 'node:path';
import {createHash,randomUUID} from 'node:crypto';

export const CHECKOUT_RECORD_LIMIT=262144;
const tag=/^[A-Za-z0-9._:-]{1,128}$/;
const fail=(ok,code)=>{if(!ok)throw new TypeError(code);};
const digest=raw=>createHash('sha256').update(raw).digest('hex');
export function checkoutPaths(outputDir,intentId) {
 fail(typeof outputDir==='string'&&isAbsolute(outputDir)&&!outputDir.includes('\0'),'ABSOLUTE_PRIVATE_EVIDENCE_DIRECTORY_REQUIRED');
 fail(typeof intentId==='string'&&tag.test(intentId),'TRUSTED_BUYER_AND_STABLE_INTENT_REQUIRED');
 const base=join(outputDir,digest(intentId));
 return {evidencePath:base+'.json',checkpointPath:base+'.checkpoint.json',bodyPath:base+'.body-checkpoint.json'};
}
async function privateDirectory(directory) {
 const info=await lstat(directory);
 fail(info.isDirectory()&&!info.isSymbolicLink(),'EVIDENCE_PATH_NOT_DIRECTORY');
}
export async function readCheckoutRecord(file,{optional=false}={}) {
 await privateDirectory(dirname(file));
 let handle;
 try {handle=await open(file,constants.O_RDONLY|(constants.O_NOFOLLOW??0));}
 catch(error){if(optional&&error.code==='ENOENT')return null;throw error;}
 try {
  const info=await handle.stat();
  fail(info.isFile()&&info.size<=CHECKOUT_RECORD_LIMIT,'CHECKOUT_RECORD_INVALID_OR_TOO_LARGE');
  const bytes=await handle.readFile();
  fail(bytes.length<=CHECKOUT_RECORD_LIMIT,'CHECKOUT_RECORD_INVALID_OR_TOO_LARGE');
  const value=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(bytes));
  return {value,bytes:bytes.length,sha256:digest(bytes),path:file};
 } finally {await handle.close();}
}
export async function createCheckoutRecord(file,value) {
 await privateDirectory(dirname(file));
 const bytes=Buffer.from(JSON.stringify(value,null,2)+'\n');
 fail(bytes.length<=CHECKOUT_RECORD_LIMIT,'CHECKOUT_RECORD_INVALID_OR_TOO_LARGE');
 const temporary=join(dirname(file),'.checkout-'+randomUUID()+'.tmp');
 const handle=await open(temporary,constants.O_WRONLY|constants.O_CREAT|constants.O_EXCL|(constants.O_NOFOLLOW??0),0o600);
 try {
  try {await handle.writeFile(bytes);await handle.sync();} finally {await handle.close();}
  // Link publishes complete bytes with create-only semantics. A failed write
  // leaves no empty terminal record, and a concurrent winner is never replaced.
  await link(temporary,file);
  const directory=await open(dirname(file),'r');
  try {await directory.sync();} finally {await directory.close();}
  return {value,bytes:bytes.length,sha256:digest(bytes),path:file};
 } finally {
  await unlink(temporary).catch(error=>{if(error.code!=='ENOENT')throw error;});
 }
}


/** Complete a publication interrupted between hard-link publication and removal
 * of this writer's temporary name. The published bytes are never replaced. */
export async function finishCheckoutRecordPublication(file) {
 await privateDirectory(dirname(file));
 let target;
 try {target=await lstat(file);}catch(error){if(error.code==='ENOENT')return;throw error;}
 fail(target.isFile()&&!target.isSymbolicLink(),'CHECKOUT_RECORD_INVALID_OR_TOO_LARGE');
 if(target.nlink<=1)return;
 let removed=false;
 for(const name of await readdir(dirname(file))) {
  if(!/^\.checkout-[a-f0-9]{8}(?:-[a-f0-9]{4}){3}-[a-f0-9]{12}\.tmp$/.test(name))continue;
  const candidate=join(dirname(file),name);
  let info;
  try {info=await lstat(candidate);}catch(error){if(error.code==='ENOENT')continue;throw error;}
  if(!info.isFile()||info.isSymbolicLink()||info.dev!==target.dev||info.ino!==target.ino)continue;
  const current=await lstat(file);
  fail(current.dev===target.dev&&current.ino===target.ino,'CHECKOUT_PUBLISHED_FILE_CHANGED');
  try {await unlink(candidate);removed=true;}catch(error){if(error.code!=='ENOENT')throw error;}
 }
 if(removed) {
  const parent=await open(dirname(file),'r');
  try {await parent.sync();}finally{await parent.close();}
 }
}

// MIT — SCF SF82: one original approved buyer attempt to independently observed evidence.
// Trusted operator-host adapter; not an agent-facing signer, new payment controller or ledger.
import { createHash } from 'node:crypto';
import { stat } from 'node:fs/promises';
import { isAbsolute } from 'node:path';
import { checkStellarTransaction, createOfficialEventDecoder } from '../sf43-agent-commerce/verify.mjs';
import { captureBuyerResult, captureBuyerError, aggregateOutcomes } from '../sf52-buyer-outcomes/outcomes.mjs';
import { sf81ReconciliationRecord } from '../sf82-chain-transfer-reconcile/record.mjs';
import {checkoutPaths,readCheckoutRecord,createCheckoutRecord,finishCheckoutRecordPublication} from './checkpoint.mjs';

const tag = /^[A-Za-z0-9._:-]{1,128}$/; // Original SF52 observation identity limit.
const payer = /^[GC][A-Z2-7]{55}$/;
const isObject = v => v !== null && typeof v === 'object' && !Array.isArray(v);

async function bodyEvidence(response, maxBytes, timeoutMs) {
  if (!response || typeof response.clone !== 'function' || !Number.isInteger(response.status) ||
      response.status < 200 || response.status >= 300) return { status: 'NO_SUCCESSFUL_HTTP_BODY' };
  let clone;
  try { clone = response.clone(); } catch { return { status: 'BODY_NOT_CLONEABLE' }; }
  if (!clone.body || typeof clone.body.getReader !== 'function') return { status: 'NO_BODY_STREAM' };
  const hash = createHash('sha256');
  const reader = clone.body.getReader();
  let size = 0, timer;
  const deadline = new Promise(resolve => {
    timer = setTimeout(() => resolve({ timedOut: true }), timeoutMs);
  });
  try {
    for (;;) {
      // The race also handles late read rejection after a timeout; no ignored
      // read can become an unhandled rejection after evidence is returned.
      const next = await Promise.race([reader.read(), deadline]);
      if (next.timedOut) return { status: 'BODY_CAPTURE_TIMED_OUT', timeoutMs };
      const { done, value } = next;
      if (done) return { status: 'HTTP_BODY_OBSERVED', httpStatus: response.status,
        bodySha256: hash.digest('hex'), bodyBytes: size };
      if (!(value instanceof Uint8Array)) return { status: 'INVALID_BODY_CHUNK' };
      size += value.byteLength;
      if (size > maxBytes) return { status: 'BODY_OVER_LIMIT', limitBytes: maxBytes };
      hash.update(value);
    }
  } catch { return { status: 'BODY_READ_FAILED' }; }
  finally {
    clearTimeout(timer);
    try { void reader.cancel().catch(() => {}); } catch {}
    try { reader.releaseLock(); } catch {}
  }
}

// SF81's reservation is already durable in its original SF36 ledger. Export ONLY
// fixed non-secret fields; never persist operator policy, TTY transcript or wallet.
function reservationMetadata(raw) {
  if (!isObject(raw)) return null;
  const r = {};
  for (const [from, to] of [['outcome', 'outcome'], ['request_id','requestId'],
    ['request_sha256','requestSha256'], ['asset','asset'],
    ['network','network'], ['reserved_atomic_units','reservedAtomicUnits']]) {
    const v = raw[from];
    if (typeof v === 'string' && v.length <= 160) r[to] = v;
  }
  return Object.keys(r).length ? r : null;
}

/**
 * Invoke original SF81 exactly once; feed original SF31 result to SF52, and a
 * compatible network-bound receipt to ORIGINAL SF43 RPC/SEP-41 verification.
 *
 * buyer: the trusted host's existing OperatorApprovedBuyer (no new approval).
 * call:  exact existing SF81 call options, including trusted signer and intentId.
 * outputDir: pre-existing private absolute directory, chosen by the operator.
 * trustedPayer: actual payer returned/bound by the trusted signer, never seller data.
 * decodeContractEvent: original createOfficialEventDecoder() or trusted SDK decoder.
 * captureBody: bounded opt-in body-hash from cloned successful HTTP Response.
 * rpcEndpoint/rpcFetch: SF43's own restricted endpoint and HTTP implementation;
 *                     loopback override is intended ONLY for focused local tests.
 * Returns {result,error,evidencePath,report}. Never blindly retries a signed call.
 */
export async function executeWithEvidence({buyer, call, outputDir, trustedPayer,
  decodeContractEvent, rpcEndpoint, rpcFetch, captureBody = false,
  maxBodyBytes = 1_048_576, bodyCaptureTimeoutMs = 15000,
  observedAt = new Date().toISOString()} = {}) {
  if (!isObject(buyer) || typeof buyer.call !== 'function' || !isObject(call) ||
      typeof call.intentId !== 'string' || !tag.test(call.intentId))
    throw new TypeError('TRUSTED_BUYER_AND_STABLE_INTENT_REQUIRED');
  if (typeof outputDir !== 'string' || !isAbsolute(outputDir) || outputDir.includes('\0'))
    throw new TypeError('ABSOLUTE_PRIVATE_EVIDENCE_DIRECTORY_REQUIRED');
  if (trustedPayer !== undefined && (typeof trustedPayer !== 'string' || !payer.test(trustedPayer)))
    throw new TypeError('TRUSTED_STELLAR_PAYER_INVALID');
  if (decodeContractEvent !== undefined && typeof decodeContractEvent !== 'function')
    throw new TypeError('DECODER_MUST_BE_TRUSTED_FUNCTION');
  if (rpcFetch !== undefined && typeof rpcFetch !== 'function') throw new TypeError('RPC_FETCH_INVALID');
  if (typeof captureBody !== 'boolean' || !Number.isSafeInteger(maxBodyBytes) ||
      maxBodyBytes < 1 || maxBodyBytes > 8_388_608)
    throw new TypeError('BODY_CAPTURE_LIMIT_INVALID');
  if (!Number.isSafeInteger(bodyCaptureTimeoutMs) || bodyCaptureTimeoutMs < 1 || bodyCaptureTimeoutMs > 60000)
    throw new TypeError('BODY_CAPTURE_TIMEOUT_INVALID');
  // Validate original SF52's exact timestamp contract before a buyer can sign.
  // This preflight observation is never persisted as an actual buyer attempt.
  captureBuyerError({intentId:call.intentId,error:{paymentSent:false,code:'EVIDENCE_PREFLIGHT'},observedAt});
  const directory = await stat(outputDir);
  if (!directory.isDirectory()) throw new TypeError('EVIDENCE_PATH_NOT_DIRECTORY');
  const {evidencePath,checkpointPath,bodyPath}=checkoutPaths(outputDir,call.intentId);
  // Fail before invoking a signer when this exact intent already has a terminal
  // report. Cross-process paid-attempt uniqueness remains SF36's original job.
  try {
    await stat(evidencePath);
    throw new Error('TERMINAL_EVIDENCE_ALREADY_EXISTS_USE_EXISTING_SF36_LEDGER');
  } catch (err) {
    if (err.code !== 'ENOENT') throw err;
  }

  // A returned original buyer result is a durable continuation even if its
  // later RPC observation or terminal file was interrupted.
  if (await readCheckoutRecord(checkpointPath,{optional:true}))
    throw new Error('CHECKOUT_CHECKPOINT_EXISTS_USE_RECOVERY');

  let result = null, error = null;
  try { result = await buyer.call(call); }
  catch (e) { error = e; }
  // Retain the original approved record while it is still available. The
  // smaller SF52 observation/reservation summary cannot reconstruct this later.
  let reconciliation = {status:'UNAVAILABLE', reason:'NO_ELIGIBLE_ORIGINAL_SF81_RESULT'};
  if (!error) {
    try { reconciliation = {status:'AVAILABLE', record:sf81ReconciliationRecord(result)}; }
    catch { /* Free, unsupported or incomplete outcomes retain no invented record. */ }
  }
  // The error adapter conservatively marks errors with UNKNOWN paymentSent as
  // potentially signed, not an unapproved, safely repeatable operation.
  const observedError = error && typeof error.paymentSent !== 'boolean' ?
    { paymentSent: true, code: 'UNKNOWN_EXECUTION_PHASE' } : error;
  const base = error ? captureBuyerError({intentId:call.intentId,error:observedError,observedAt}) :
    captureBuyerResult(result,{observedAt});
  const checkpoint=await createCheckoutRecord(checkpointPath,{
    schema:'scf82.checkout-checkpoint.v1',intentId:call.intentId,observedAt,
    trustedPayer:trustedPayer??null,observation:base,reconciliation,
    operatorReservation:reservationMetadata(result?.operatorReservation??error?.operatorReservation),
    captureBody,maxBodyBytes,bodyCaptureTimeoutMs,
  });
  let chain = null, delivery = null;
  let bodyCapture = {status:captureBody ? 'NO_SUCCESSFUL_PAID_BODY' : 'NOT_REQUESTED'};
  if (!error) {
    if (captureBody && base.buyer.requirement) {
      const candidate = await bodyEvidence(result.response,maxBodyBytes,bodyCaptureTimeoutMs);
      bodyCapture = candidate;
      if (candidate.status === 'HTTP_BODY_OBSERVED') {
        delivery = {status:candidate.status,httpStatus:candidate.httpStatus,
          bodySha256:candidate.bodySha256};
      }
    }
  }
  // Retain the completed body-hash observation before the independent RPC work.
  await createCheckoutRecord(bodyPath,{schema:'scf82.checkout-body-checkpoint.v1',
    intentId:call.intentId,checkpointSha256:checkpoint.sha256,bodyCapture});
  if (!error) chain=await observeCheckoutChain(base,{trustedPayer,decodeContractEvent,rpcEndpoint,rpcFetch});

  const observation = {...base, ...(chain ? {chain} : {}), ...(delivery ? {delivery} : {})};
  const report = aggregateOutcomes([observation]);
  const envelope = {
    schema:'scf82.checkout-evidence.v1', intentId:call.intentId, observedAt,
    operatorReservation:reservationMetadata(result?.operatorReservation ?? error?.operatorReservation),
    observation, report, bodyCapture, reconciliation,
    sourceCheckpoint:{path:checkpointPath,sha256:checkpoint.sha256},
    notes:'Original SF43 observes the approved network, transaction and exact SEP-41 transfer. HTTP delivery and original SF36 accounting are recorded separately.',
  };
  await createCheckoutRecord(evidencePath,envelope);
  return { result, error, evidencePath, report };
}

async function observeCheckoutChain(base,{trustedPayer,decodeContractEvent,rpcEndpoint,rpcFetch}={}) {
  const terms=base.buyer.requirement,receipt=base.buyer.receipt;
  if (!(trustedPayer&&['stellar:testnet','stellar:pubnet'].includes(terms?.network)&&
      receipt?.success===true&&receipt.network===terms.network&&/^[0-9a-f]{64}$/.test(receipt.transaction||''))) return null;
  let decoder=decodeContractEvent;
  if (!decoder) {
    try {decoder=await createOfficialEventDecoder();}
    catch {decoder=undefined;}
  }
  return checkStellarTransaction({
    receipt:{...receipt,payer:trustedPayer},
    expected:{network:terms.network,asset:terms.asset,payTo:terms.payTo,amount:terms.amount,payer:trustedPayer},
    ...(decoder?{decodeContractEvent:decoder}:{}),
    ...(rpcEndpoint!==undefined?{rpcEndpoint}:{}),
    ...(rpcFetch!==undefined?{fetchImpl:rpcFetch}:{}),
  });
}

function terminalRecord(record,intentId) {
  const value=record?.value;
  if (!isObject(value)||value.schema!=='scf82.checkout-evidence.v1'||value.intentId!==intentId||
      value.observation?.intentId!==intentId) throw new TypeError('CHECKOUT_TERMINAL_RECORD_INVALID');
  aggregateOutcomes([value.observation]);
  return {evidencePath:record.path,report:value.report,checkpointPath:value.sourceCheckpoint?.path??null,
    recovered:false,evidenceSha256:record.sha256};
}

/** Finish observation of a saved original buyer result. This API never invokes
 * a buyer, signer, approval, reservation or merchant request. */
export async function recoverCheckoutEvidence({outputDir,intentId,trustedPayer,
  decodeContractEvent,rpcEndpoint,rpcFetch}={}) {
  const {evidencePath,checkpointPath,bodyPath}=checkoutPaths(outputDir,intentId);
  if (trustedPayer!==undefined&&(typeof trustedPayer!=='string'||!payer.test(trustedPayer)))
    throw new TypeError('TRUSTED_STELLAR_PAYER_INVALID');
  if (decodeContractEvent!==undefined&&typeof decodeContractEvent!=='function')
    throw new TypeError('DECODER_MUST_BE_TRUSTED_FUNCTION');
  if (rpcFetch!==undefined&&typeof rpcFetch!=='function')throw new TypeError('RPC_FETCH_INVALID');
  for(const path of [checkpointPath,bodyPath,evidencePath])await finishCheckoutRecordPublication(path);
  const terminal=await readCheckoutRecord(evidencePath,{optional:true});
  if (terminal)return terminalRecord(terminal,intentId);
  const checkpoint=await readCheckoutRecord(checkpointPath),saved=checkpoint.value;
  if (!isObject(saved)||saved.schema!=='scf82.checkout-checkpoint.v1'||saved.intentId!==intentId||
      saved.observation?.intentId!==intentId||saved.observation?.observedAt!==saved.observedAt||
      typeof saved.captureBody!=='boolean'||!isObject(saved.reconciliation)||
      !['AVAILABLE','UNAVAILABLE'].includes(saved.reconciliation.status)||
      (saved.trustedPayer??null)!==(trustedPayer??null))
    throw new TypeError('CHECKOUT_CHECKPOINT_BINDING_MISMATCH');
  aggregateOutcomes([saved.observation]);
  if (saved.reconciliation.status==='AVAILABLE'&&
      (saved.reconciliation.record?.intentId!==intentId||
       saved.reconciliation.record?.operatorReservation?.request_id!==intentId))
    throw new TypeError('CHECKOUT_CHECKPOINT_BINDING_MISMATCH');
  const bodyRecord=await readCheckoutRecord(bodyPath,{optional:true});
  if (bodyRecord&&(bodyRecord.value?.schema!=='scf82.checkout-body-checkpoint.v1'||
      bodyRecord.value?.intentId!==intentId||bodyRecord.value?.checkpointSha256!==checkpoint.sha256||
      !isObject(bodyRecord.value?.bodyCapture)))
    throw new TypeError('CHECKOUT_BODY_CHECKPOINT_BINDING_MISMATCH');
  const bodyCapture=bodyRecord?.value.bodyCapture??{status:saved.captureBody?'CAPTURE_INTERRUPTED':'NOT_REQUESTED'};
  let delivery=null;
  if (bodyCapture.status==='HTTP_BODY_OBSERVED') {
    if (!Number.isSafeInteger(bodyCapture.httpStatus)||bodyCapture.httpStatus<200||bodyCapture.httpStatus>=300||
        !/^[0-9a-f]{64}$/.test(bodyCapture.bodySha256??'')||!Number.isSafeInteger(bodyCapture.bodyBytes)||
        bodyCapture.bodyBytes<0||bodyCapture.bodyBytes>saved.maxBodyBytes)
      throw new TypeError('CHECKOUT_BODY_CHECKPOINT_INVALID');
    delivery={status:bodyCapture.status,httpStatus:bodyCapture.httpStatus,bodySha256:bodyCapture.bodySha256};
  }
  const chain=await observeCheckoutChain(saved.observation,{trustedPayer,decodeContractEvent,rpcEndpoint,rpcFetch});
  const observation={...saved.observation,...(chain?{chain}:{}),...(delivery?{delivery}:{})};
  const report=aggregateOutcomes([observation]);
  const envelope={
    schema:'scf82.checkout-evidence.v1',intentId,observedAt:saved.observedAt,
    operatorReservation:saved.operatorReservation,observation,report,bodyCapture,reconciliation:saved.reconciliation,
    sourceCheckpoint:{path:checkpointPath,sha256:checkpoint.sha256},
    recovery:{schema:'scf82.checkout-recovery.v1',recoveredAt:new Date().toISOString(),
      method:'original returned SF81 result and independent SF43 observation',buyerInvocations:0},
    notes:'Original SF43 observes the approved network, transaction and exact SEP-41 transfer. HTTP delivery and original SF36 accounting are recorded separately.',
  };
  let written;
  try {written=await createCheckoutRecord(evidencePath,envelope);}
  catch(error) {
    if (error.code!=='EEXIST')throw error;
    return terminalRecord(await readCheckoutRecord(evidencePath),intentId);
  }
  return {evidencePath,report,checkpointPath,recovered:true,evidenceSha256:written.sha256};
}

