    if (!row?.before || row.before.retired) fail('RELEASE_CATALOG_NOT_LISTED', 'Choose a currently listed route to withdraw.');
    if (typeof reason !== 'string' || !reason.trim() || reason.length > 256 || /[\x00-\x1f\x7f]/.test(reason))
