  const intentId = 'dataset:' + key;
  c.operation = {...c.operation, intentId, url:u.href, expect:{...c.operation.expect, maxAtomic:cap.toString()}};
  c.captureBody = false;
  c.evidenceDir = join(definition.directory, 'evidence');
