async function observedSource(file) {
  try {
    const bytes = await readBytes(file, 16777216);
    return { file, bytes:bytes.length, sha256:digest(bytes) };
  } catch (problem) {
    return { file, errorCode:safeCode(problem?.code, 'DIAGNOSTIC_SOURCE_UNAVAILABLE') };
  }
