// MIT — Offline saved-catalog selection for the existing SF88 review command.
import { createHash } from 'node:crypto';
import { open, unlink } from 'node:fs/promises';
import { abs, bytes, InputError, need, operation, preparedFrom, responseFile } from './config.mjs';
import { loadOperationTicket, operationTicketView } from './operation-ticket.mjs';
import { normalizeOperationHeaders, readOperationHeaders } from './request-headers.mjs';
import { readRequestBody, requestBodyPin, prepareMultipartFile } from './request-body.mjs';

const object = x => x !== null && typeof x === 'object' && !Array.isArray(x);
const required = ['--discovery','--row','--accept','--intent-id','--url','--method','--out'];
const optional = ['--body-file','--content-type','--headers-file','--ticket-file','--ticket-header','--response-out','--form-file','--form-out'];
function index(value) {
  need(typeof value === 'string' && /^(0|[1-9][0-9]*)$/.test(value) &&
    Number.isSafeInteger(Number(value)), 'EXPLICIT_SELECTION_INDEX_REQUIRED');
  return Number(value);
}
function https(value) {
  let url;
  try { url = new URL(value); } catch { throw new InputError('DISCOVERED_RESOURCE_URL_INVALID'); }
  need(url.protocol === 'https:' && !url.username && !url.password && !url.hash,
    'DISCOVERED_RESOURCE_HTTPS_REQUIRED');
  return url;
}

/** Shared by the original CLI and Atlas. Pure preparation: no I/O or signer. */
export function prepareReview(raw, selection) {
  need(raw instanceof Uint8Array && raw.byteLength <= 1048576, 'INVALID_DISCOVERY_FILE');
  need(object(selection) && Object.keys(selection).every(key =>
    ['rowIndex','acceptIndex','intentId','url','method','bodyFile','bodyBytes','bodySha256','headers','ticketFile','ticketHeader','responseOut'].includes(key)),
    'PREPARE_EXPLICIT_SELECTION_REQUIRED');
  const {rowIndex, acceptIndex, intentId, url, method, bodyFile, headers, ticketFile, ticketHeader} = selection;
  need(typeof method === 'string' && ['GET','HEAD','POST','PUT','PATCH','DELETE'].includes(method),
    'INVALID_METHOD');
  need(Number.isSafeInteger(rowIndex) && rowIndex >= 0 &&
    Number.isSafeInteger(acceptIndex) && acceptIndex >= 0, 'EXPLICIT_SELECTION_INDEX_REQUIRED');
  let saved;
  try { saved = JSON.parse(new TextDecoder('utf-8', {fatal:true}).decode(raw)); }
  catch { throw new InputError('DISCOVERY_JSON_INVALID'); }
  need(object(saved), 'INVALID_SAVED_DISCOVERY');
  let rows, source = null, sourceEnvelope;
  if (saved.schema === 'scf61-observed-native-page-v1') {
    need(saved.readOnly === true && saved.paidOrSettled === false &&
      !['resources','items','originalListings'].some(key => Object.hasOwn(saved,key)) &&
      (saved.sourceUrl === undefined || typeof saved.sourceUrl === 'string'),
      'INVALID_SAVED_DISCOVERY');
    rows = saved.nativeProviderRows;
    source = saved.sourceUrl ?? null;
    sourceEnvelope = 'resources';
  } else if (saved.mode === 'ORIGINAL_UNSIGNED_CATALOG') {
    need(!Object.hasOwn(saved, 'resources') && !Object.hasOwn(saved, 'items') &&
      ['resources','items'].includes(saved.sourceEnvelope) &&
      typeof saved.source === 'string', 'INVALID_SAVED_DISCOVERY');
    rows = saved.originalListings; source = saved.source; sourceEnvelope = saved.sourceEnvelope;
  } else {
    const resources = Object.hasOwn(saved, 'resources'), items = Object.hasOwn(saved, 'items');
    need(resources !== items && !Object.hasOwn(saved, 'originalListings'), 'INVALID_SAVED_DISCOVERY');
    sourceEnvelope = resources ? 'resources' : 'items'; rows = saved[sourceEnvelope];
  }
  need(Array.isArray(rows) && rowIndex < rows.length && object(rows[rowIndex]), 'DISCOVERY_ROW_NOT_FOUND');
  const row = rows[rowIndex];
  need(Array.isArray(row.accepts) && row.accepts.length >= 1 && row.accepts.length <= 32 &&
    acceptIndex < row.accepts.length && object(row.accepts[acceptIndex]), 'DISCOVERY_ACCEPT_NOT_FOUND');
  need(row.type === undefined || row.type === 'http', 'HTTP_RESOURCE_REQUIRED');
  const advertised = https(typeof row.resource === 'string' ? row.resource : row.resource?.url);
  const requested = https(url);
  // The operator supplies concrete query values. Selecting another host/path is
  // a different offer; templates must first be resolved in its source workflow.
  need(!/[{}]|%7[bd]/i.test(advertised.pathname) &&
    requested.origin === advertised.origin && requested.pathname === advertised.pathname,
    'CONCRETE_URL_MUST_MATCH_SELECTED_RESOURCE_PATH');
  const input = row.extensions?.bazaar?.info?.input;
  need(input?.type === undefined || input.type === 'http', 'HTTP_RESOURCE_REQUIRED');
  need(input?.method === undefined || input.method === method, 'DISCOVERED_METHOD_MISMATCH');
  const accepted = row.accepts[acceptIndex];
  need(Number.isInteger(accepted.maxTimeoutSeconds) && accepted.maxTimeoutSeconds >= 1 &&
    accepted.maxTimeoutSeconds <= 86400 &&
    (accepted.extra === undefined || object(accepted.extra)), 'INVALID_DISCOVERED_REQUIREMENT');
  const expect = { scheme:accepted.scheme, network:accepted.network, asset:accepted.asset,
    payTo:accepted.payTo, maxAtomic:accepted.amount, maxTimeoutSeconds:accepted.maxTimeoutSeconds };
  if (accepted.extra?.paymentFlow !== undefined) expect.paymentFlow = accepted.extra.paymentFlow;
  const op = operation({intentId, url:requested.href, method, expect,
    ...(bodyFile === undefined ? {} : {bodyFile}), ...(headers === undefined ? {} : {headers}),
    ...(selection.bodySha256===undefined?{}:{bodySha256:selection.bodySha256,bodyBytes:selection.bodyBytes}),
    ...(ticketFile === undefined ? {} : {ticketFile}), ...(ticketHeader === undefined ? {} : {ticketHeader})});
  const origin = preparedFrom({schema:'stellar-forge.sf88.saved-discovery.v1',
    discoveryFileSha256:createHash('sha256').update(raw).digest('hex'), source, sourceEnvelope,
    rowIndex, acceptIndex, originalListing:structuredClone(row)});
  const draft = {operation:op, captureBody:false, preparedFrom:origin};
  const asset = row.extensions?.['stellar-forge-asset'];
  if (asset !== undefined) {
    need(object(asset) && asset.schema === 'stellar-forge.asset-product.v1' &&
      Object.keys(asset).every(key => ['schema','sha256','bytes','contentType','downloadName'].includes(key)) &&
      method === 'GET' && bodyFile === undefined && requested.href === advertised.href &&
      typeof asset.downloadName === 'string' && asset.downloadName.length > 0 &&
      typeof asset.contentType === 'string' && asset.contentType === row.resource?.mimeType,
      'INVALID_ASSET_PRODUCT');
    need(selection.responseOut !== undefined, 'ASSET_RESPONSE_DESTINATION_REQUIRED');
    need(typeof asset.sha256 === 'string' && typeof asset.bytes === 'number', 'INVALID_ASSET_PRODUCT');
    // The output filename remains the buyer's explicit choice, never a path
    // obtained from Content-Disposition or a merchant-controlled downloadName.
    draft.responseFile = {destination:selection.responseOut, maxBytes:Math.max(1,asset.bytes),
      expectedSha256:asset.sha256, expectedBytes:asset.bytes, expectedContentType:asset.contentType};
    responseFile(draft);
  } else if (selection.responseOut !== undefined) {
    draft.responseFile = {destination:selection.responseOut};
    responseFile(draft);
  }
  const data = Buffer.from(JSON.stringify(draft, null, 2) + '\n');
  need(data.length <= 65536, 'PREPARED_CONFIG_EXCEEDS_CONFIG_LIMIT');
  return {draft, data, configSha256:createHash('sha256').update(data).digest('hex')};
}

/** Original file-based CLI; output remains private, create-only and fsynced. */
export async function prepare(args) {
  need(args.length >= required.length * 2 && args.length % 2 === 0, 'PREPARE_EXPLICIT_SELECTION_REQUIRED');
  const flags = new Map();
  for (let i = 0; i < args.length; i += 2) {
    need([...required, ...optional].includes(args[i]) && !flags.has(args[i]) &&
      typeof args[i + 1] === 'string' && args[i + 1].length > 0, 'INVALID_PREPARE_FLAGS');
    flags.set(args[i], args[i+1]);
  }
  need(required.every(key => flags.has(key)), 'PREPARE_EXPLICIT_SELECTION_REQUIRED');
  const rowIndex = index(flags.get('--row')), acceptIndex = index(flags.get('--accept'));
  const destination = abs(flags.get('--out'), 'DRAFT_PATH_MUST_BE_ABSOLUTE');
  const raw = await bytes(flags.get('--discovery'), 1048576, 'INVALID_DISCOVERY_FILE');
  let headers = flags.has('--headers-file') ? await readOperationHeaders(flags.get('--headers-file')) : {};
  if (flags.has('--content-type')) {
    const explicit = normalizeOperationHeaders({'Content-Type':flags.get('--content-type')});
    need(headers['Content-Type'] === undefined || headers['Content-Type'] === explicit['Content-Type'],
      'PREPARE_CONTENT_TYPE_HEADER_CONFLICT');
    headers = {...headers,...explicit};
  }
  need(flags.has('--form-file')===flags.has('--form-out')&&!(flags.has('--form-file')&&flags.has('--body-file')),'INVALID_FORM_PREPARATION_FLAGS');
  let request={};
  if (flags.has('--form-file')) {
    need(!headers['Content-Type'],'FORM_CONTENT_TYPE_IS_GENERATED');
    const form=JSON.parse(new TextDecoder('utf-8',{fatal:true}).decode(await bytes(flags.get('--form-file'),65536,'INVALID_FORM_FILE')));
    const staged=await prepareMultipartFile(form,abs(flags.get('--form-out'),'FORM_OUTPUT_PATH_REQUIRED'));
    request={bodyFile:staged.bodyFile,bodyBytes:staged.bodyBytes,bodySha256:staged.bodySha256};
    headers={...headers,...staged.headers};
  } else if (flags.has('--body-file')) {
    request={bodyFile:flags.get('--body-file')};
    Object.assign(request,requestBodyPin(await readRequestBody(request)));
  }
  const {draft, data, configSha256} = prepareReview(raw, {rowIndex,acceptIndex,
    intentId:flags.get('--intent-id'),url:flags.get('--url'),method:flags.get('--method'),
    ...request,
    ...(Object.keys(headers).length ? {headers} : {}),
    ...(flags.has('--ticket-file') ? {ticketFile:flags.get('--ticket-file')} : {}),
    ...(flags.has('--ticket-header') ? {ticketHeader:flags.get('--ticket-header')} : {}),
    ...(flags.has('--response-out') ? {responseOut:flags.get('--response-out')} : {})});
  const op = draft.operation, origin = draft.preparedFrom;
  const ticket = await loadOperationTicket(op, {requireCurrent:true});
  let file;
  try { file = await open(destination, 'wx', 0o600); }
  catch (error) { throw new InputError(error.code === 'EEXIST' ? 'DRAFT_DESTINATION_EXISTS' : 'DRAFT_DESTINATION_UNAVAILABLE'); }
  try { await file.writeFile(data); await file.sync(); }
  catch {
    await file.close().catch(() => {});
    await unlink(destination).catch(() => {});
    throw new InputError('DRAFT_CONFIG_WRITE_FAILED');
  }
  await file.close();
  return {mode:'OFFLINE_CONFIG_PREPARED', configPath:destination,
    configSha256,
    sourceFileSha256:origin.discoveryFileSha256, rowIndex, acceptIndex,
    intentId:op.intentId, sellerUrl:op.url, method:op.method, acceptedTerms:op.expect,
    requestHeaderNames:Object.keys(op.headers),
    operationTicket:operationTicketView(ticket),
    ...(draft.responseFile ? {responseFile:draft.responseFile} : {}),
    sourceStatus:'SAVED_UNVERIFIED_DISCOVERY',
    next:'Review this config with --review; add trusted operator settings separately before execution'};
}

// SPDX-License-Identifier: MIT
// OS-owned single-writer lifetime for a private local directory.
import { createHash } from 'node:crypto';
import { constants } from 'node:fs';
import { open, lstat, realpath } from 'node:fs/promises';
import { isAbsolute, join, resolve } from 'node:path';
import { createServer } from 'node:net';
import { spawnSync } from 'node:child_process';
import { InputError } from './config.mjs';

function requireLock(condition, code) {
  if (!condition) throw new InputError(code);
}
function privateOwned(info, directory) {
  return (directory ? info.isDirectory() : info.isFile()) &&
    !info.isSymbolicLink() &&
    (process.platform === 'win32' || (info.mode & 0o077) === 0 &&
      typeof process.getuid === 'function' && info.uid === process.getuid());
}
async function sameLockFile(handle, path, code) {
  const [opened, named] = await Promise.all([handle.stat(), lstat(path)]);
  requireLock(privateOwned(opened, false) && privateOwned(named, false) &&
    opened.nlink === 1 && named.nlink === 1 &&
    opened.dev === named.dev && opened.ino === named.ino, code);
}

/**
 * Return an idempotent asynchronous release function. Linux keeps the same
 * private inode in place and holds flock through the parent's open descriptor.
 * Windows and other Unix platforms keep the original named-pipe/socket scheme.
 */
export async function lockPrivateDirectory({
  directory, filename, namespace, busyCode, unavailableCode,
}) {
  requireLock(typeof unavailableCode === 'string' && /^[A-Z0-9_]+$/.test(unavailableCode) &&
    typeof busyCode === 'string' && /^[A-Z0-9_]+$/.test(busyCode),
  'PRIVATE_DIRECTORY_LOCK_OPTIONS_INVALID');
  requireLock(typeof directory === 'string' && isAbsolute(directory) &&
    resolve(directory) === directory && !directory.includes('\0') &&
    typeof filename === 'string' && /^[.a-zA-Z0-9_-]{1,120}\.lock$/.test(filename) &&
    typeof namespace === 'string' && /^[a-zA-Z0-9_-]{1,80}$/.test(namespace),
  unavailableCode);
  let root;
  try {
    root = await lstat(directory);
    requireLock(privateOwned(root, true) && await realpath(directory) === directory, unavailableCode);
  } catch (error) {
    if (error instanceof InputError) throw error;
    throw new InputError(unavailableCode);
  }

  if (process.platform === 'linux') {
    const path = join(directory, filename);
    let handle;
    try {
      handle = await open(path, constants.O_CREAT | constants.O_RDWR | constants.O_NOFOLLOW, 0o600);
      await sameLockFile(handle, path, unavailableCode);
      // flock(2) follows the open file description shared by inherited fd 3 and
      // this parent handle. The short child exits while the parent retains it.
      const result = spawnSync('flock', [
        '--exclusive', '--nonblock', '--conflict-exit-code', '73', '3',
      ], { stdio: ['ignore', 'ignore', 'pipe', handle.fd], timeout: 10000 });
      requireLock(!result.error && result.status === 0,
        !result.error && result.status === 73 ? busyCode : unavailableCode);
      await sameLockFile(handle, path, unavailableCode);
      const currentRoot = await lstat(directory);
      requireLock(currentRoot.dev === root.dev && currentRoot.ino === root.ino &&
        privateOwned(currentRoot, true) && await realpath(directory) === directory, unavailableCode);
      let released;
      return () => released ??= handle.close();
    } catch (error) {
      await handle?.close().catch(() => {});
      if (error instanceof InputError) throw error;
      throw new InputError(unavailableCode);
    }
  }

  const name = namespace + '-' + createHash('sha256').update(directory).digest('hex');
  const address = process.platform === 'win32'
    ? '\\\\.\\pipe\\' + name : join(directory, filename.replace(/\.lock$/, '.sock'));
  const server = createServer(socket => socket.destroy());
  try {
    await new Promise((accept, reject) => {
      const failed = error => {
        server.close(() => {});
        reject(new InputError(error.code === 'EADDRINUSE' ? busyCode : unavailableCode));
      };
      server.once('error', failed);
      server.listen(address, () => { server.off('error', failed); accept(); });
    });
  } catch (error) {
    server.close(() => {});
    if (error instanceof InputError) throw error;
    throw new InputError(unavailableCode);
  }
  server.unref();
  let released;
  return () => released ??= new Promise((accept, reject) =>
    server.close(error => error ? reject(error) : accept()));
}

#!/usr/bin/env node
// MIT — Exact-intent operator commands; no automatic scheduling or paid retry.
import { initializeQueue, openQueue, saveQueueReport } from './queue.mjs';
import { need } from './config.mjs';

const print = value => process.stdout.write(JSON.stringify(value, null, 2) + '\n');
const commands = {init:[], enqueue:['--config'], list:[], show:['--intent'],
  execute:['--intent'], recover:['--intent'], finalize:['--intent','--workspace'], cancel:['--intent'], report:['--out'],
  'inspect-lost-output':['--intent','--workspace','--approved-request'],
  'read-lost-output':['--intent','--workspace'],
  'export-lost-output':['--intent','--workspace','--out'],
  'recover-lost-output':['--intent','--workspace','--transaction','--request-sha','--approved-request'],
  'inspect-missing-receipt':['--intent','--workspace'],
  'read-missing-receipt':['--intent','--workspace'],
  'recover-missing-receipt':['--intent','--workspace','--transaction','--request-sha']};
let signalExit;
async function main(args) {
  if (args[0] === 'operations') {
    const {main: operationsHandoff} = await import('./operations-handoff/cli.mjs');
    return operationsHandoff(args.slice(1));
  }
  if (args[0] === 'review-jobs') {
    const {main: reviewJobs} = await import('./review-jobs/cli.mjs');
    return reviewJobs(args.slice(1));
  }
  if (args[0] === 'library') {
    const {main: resourceLibrary} = await import('./resource-library/cli.mjs');
    return resourceLibrary(args.slice(1));
  }
  if (args.length === 1 && args[0] === '--help') {
    process.stdout.write('Usage: node queue-cli.mjs COMMAND --root /absolute/inbox [OPTION VALUE]\n' +
      'Commands: init | enqueue --config ABS | list | show --intent ID | execute --intent ID [--workspace ABS] | recover --intent ID | finalize --intent ID --workspace ABS [--outbox ABS --merchant-route ID] | cancel --intent ID | report --out ABS [--workspace ABS]\n' +
      'Missing receipt: inspect-missing-receipt | read-missing-receipt | recover-missing-receipt --transaction HASH --request-sha HASH; each requires --intent ID --workspace ABS. Read/recover accept --attempt ID --config-sha HASH --node ABS.\n' +
      'Lost local output: inspect-lost-output --approved-request ABS | read-lost-output | recover-lost-output --transaction HASH --request-sha HASH --approved-request ABS; each requires --intent ID --workspace ABS.\n' +
      'Operations source: operations export --inbox ABS --intent ID [--intent ID ...] --output ABS [--max-verify-bytes N] | operations inspect --file ABS. No buyer execution.\n' +
      'Delivered resources: library --help (search, preview, download and retain analyst reviews).\n' +
      'Customer review jobs: review-jobs --help (source, native request, review, delivery and recovery).\n' +
      'Execute invokes the original SF88 operator approval for one exact intent. An attempted intent is never replayed.\n');
    return;
  }
  const [command, ...rest] = args;
  need(Object.hasOwn(commands, command), 'INBOX_COMMAND_REQUIRED');
  const required = ['--root', ...commands[command]];
  const allowed = [...required, ...(['execute','report'].includes(command) ? ['--workspace'] : []),
    ...(command === 'finalize' ? ['--outbox','--merchant-route'] : []),
    ...(['read-missing-receipt','recover-missing-receipt','read-lost-output','recover-lost-output'].includes(command)?['--attempt','--config-sha','--node']:[]),
    ...(['read-missing-receipt','read-lost-output'].includes(command)?['--request-sha']:[])], flags = new Map();
  need(rest.length % 2 === 0 && rest.length >= required.length * 2 &&
    rest.length <= allowed.length * 2, 'INBOX_EXPLICIT_ARGUMENTS_REQUIRED');
  for (let i=0; i<rest.length; i+=2) {
    need(allowed.includes(rest[i]) && !flags.has(rest[i]) && typeof rest[i+1] === 'string', 'INBOX_ARGUMENT_INVALID');
    flags.set(rest[i], rest[i+1]);
  }
  need(required.every(flag => flags.has(flag)), 'INBOX_EXPLICIT_ARGUMENTS_REQUIRED');
  if (command === 'init') return print(await initializeQueue(flags.get('--root')));
  const queue = await openQueue(flags.get('--root'));
  if (command === 'enqueue') return print(await queue.enqueue(flags.get('--config')));
  if (command === 'list') return print(await queue.list());
  if (command === 'show') return print(await queue.show(flags.get('--intent')));
  if (command === 'recover') return print(await queue.recover(flags.get('--intent')));
  if (command === 'cancel') return print(await queue.cancel(flags.get('--intent')));
  if (command === 'inspect-lost-output') {
    const {inspectLostOutputAttempt}=await import('./lost-output.mjs');
    return print(await inspectLostOutputAttempt({root:queue.root,intentId:flags.get('--intent'),
      workspace:flags.get('--workspace'),approvedRequestFile:flags.get('--approved-request')}));
  }
  if (command === 'inspect-missing-receipt') {
    const {inspectMissingReceiptAttempt}=await import('./missing-receipt.mjs');
    return print(await inspectMissingReceiptAttempt({root:queue.root,intentId:flags.get('--intent'),
      workspace:flags.get('--workspace')}));
  }
  if (command === 'report') {
    const {renderQueueReport} = await import('./queue-report.mjs');
    const {readLostOutputQueueViews} = await import('./lost-output.mjs');
    return print(await saveQueueReport(flags.get('--out'), renderQueueReport({
      jobs:await readLostOutputQueueViews({root:queue.root,workspace:flags.get('--workspace')}),
      queueRoot:queue.root, accountingWorkspace:flags.get('--workspace'),
    })));
  }
