  a.mtimeMs===b.mtimeMs&&a.ctimeMs===b.ctimeMs&&a.mode===b.mode&&a.uid===b.uid&&a.nlink===b.nlink;
function json(bytes) {
  try{return JSON.parse(decoder.decode(bytes));}catch{throw new Error('SF93_SNAPSHOT_PIN_JSON_INVALID');}
